'use strict';
/* Guía (materiales de consulta) en español — parte 1: tipos de narrador y conceptos de voz y punto de vista,
   Figuras retóricas y Recursos de estilo.
   Norma de referencia: español de España (RAE/ASALE, Ortografía 2010), con indicación de la variación americana cuando importa.
   Cada entrada: n nombre · a otros nombres · d descripción · u cómo usarlo · c cuidado · x ejemplos · t en la herramienta · s véase también (nombres exactos).
   Los ejemplos sin autor son frases inventadas para ilustrar el recurso. Los títulos de obras van en cursiva (*así*). */

/* ============ TIPOS DE NARRADOR (se eligen en la ficha de cada Tomo) ============ */
NARRATORS.push(
  { key:'primeira-protagonista', name:'Narrador protagonista',
    desc:'La historia la cuenta quien la vive, en primera persona («yo»). El lector solo sabe lo que el protagonista sabe, siente y decide revelar.',
    forces:'Intimidad y voz poderosa; identificación inmediata; ideal para arcos de transformación interior y para confesiones.',
    risks:'Campo de visión limitado; difícil mostrar lo que ocurre donde el protagonista no está; la voz tiene que sostener el libro entero.',
    examples:'*Lazarillo de Tormes* (anónimo), *La familia de Pascual Duarte* (Camilo José Cela), *Nada* (Carmen Laforet), *El guardián entre el centeno* (J. D. Salinger), *Grandes esperanzas* (Charles Dickens).' },
  { key:'primeira-testemunha', name:'Narrador testigo',
    desc:'Un «yo» que observa y relata la historia de otro personaje, más central que él mismo.',
    forces:'Mantiene el misterio en torno al protagonista; permite admiración, duda o ironía por parte del observador.',
    risks:'El narrador puede volverse pasivo; obliga a justificar cómo sabe lo que cuenta.',
    examples:'*El gran Gatsby* (F. Scott Fitzgerald), las aventuras de Sherlock Holmes narradas por Watson, *Crónica de una muerte anunciada* (Gabriel García Márquez).' },
  { key:'segunda-pessoa', name:'Narrador en segunda persona',
    desc:'La narración se dirige a un «tú» (o, más raramente, a un «usted» o un «vos»), que sitúa al lector —o a un personaje interpelado— en el centro de la acción.',
    forces:'Efecto de inmersión y extrañeza; muy eficaz en textos breves, experimentales o confesionales, y para el desdoblamiento de un personaje que se habla a sí mismo.',
    risks:'Cansa en textos largos; puede provocar resistencia en el lector, que no se reconoce en lo que «hace».',
    examples:'*Aura* (Carlos Fuentes), los pasajes en «tú» de *La muerte de Artemio Cruz* (Fuentes), *Si una noche de invierno un viajero* (Italo Calvino).' },
  { key:'terceira-omnisciente', name:'Narrador omnisciente',
    desc:'Un narrador externo, en tercera persona, que lo sabe todo: los pensamientos de varios personajes, el pasado, el futuro y lo que nadie vio.',
    forces:'Amplitud épica; libertad para comentar, anticipar y moverse entre personajes, lugares y tiempos.',
    risks:'Distancia emocional; los saltos de una cabeza a otra mal controlados confunden al lector.',
    examples:'*Guerra y paz* (León Tolstói), *Fortunata y Jacinta* (Benito Pérez Galdós), *La Regenta* (Leopoldo Alas, «Clarín»).' },
  { key:'terceira-limitada', name:'Narrador equisciente (tercera persona limitada)',
    desc:'Narración en «él / ella», pero pegada a la percepción de un solo personaje cada vez (el Personaje POV): el narrador sabe lo mismo que ese personaje, ni más ni menos. En los manuales españoles se llama también narrador equisciente.',
    forces:'Equilibrio entre intimidad y flexibilidad; permite alternar el punto de vista entre Escenas o Capítulos.',
    risks:'Exige disciplina: no se puede narrar nada que el Personaje POV no perciba, recuerde o suponga.',
    examples:'*1984* (George Orwell), la serie *Harry Potter* (J. K. Rowling), *El coronel no tiene quien le escriba* (Gabriel García Márquez).' },
  { key:'terceira-objetiva', name:'Narrador objetivo (cámara)',
    desc:'El narrador solo registra lo que se ve y se oye, como una cámara, sin acceso a los pensamientos. En algunos manuales se llama también narrador deficiente o externo.',
    forces:'Subtexto y tensión; el lector deduce las emociones a partir de gestos y diálogos.',
    risks:'Puede resultar frío; pide diálogos y acciones muy expresivos.',
    examples:'*Colinas como elefantes blancos* (Ernest Hemingway), *El Jarama* (Rafael Sánchez Ferlosio), novela emblemática del objetivismo español.' },
  { key:'nao-fiavel', name:'Narrador no fiable',
    desc:'Un narrador cuya versión de los hechos no merece plena confianza, por mentira, autoengaño, ingenuidad o locura.',
    forces:'Ironía dramática, giros y relectura; convierte al lector en detective.',
    risks:'Las pistas tienen que ser limpias; una revelación gratuita se percibe como trampa.',
    examples:'*Lolita* (Vladimir Nabokov), *Los restos del día* (Kazuo Ishiguro), *El túnel* (Ernesto Sabato).' },
  { key:'multiplos', name:'Narración polifónica (varios narradores)',
    desc:'La historia se reparte entre varias voces o puntos de vista, que se completan o se contradicen.',
    forces:'Muestra el mismo mundo desde ángulos distintos; excelente para historias con varios Arcos narrativos.',
    risks:'Voces poco diferenciadas confunden; algunos hilos pueden interesar menos que otros.',
    examples:'*Mientras agonizo* (William Faulkner), *Pedro Páramo* (Juan Rulfo), *Canción de hielo y fuego* (George R. R. Martin).' },
  { key:'epistolar', name:'Narración epistolar o documental',
    desc:'El relato se compone de cartas, diarios, mensajes, informes, actas u otros documentos.',
    forces:'Verosimilitud y cercanía; los huecos entre documentos crean suspense.',
    risks:'La acción llega siempre «en diferido»; hay que justificar por qué alguien lo escribe todo.',
    examples:'*Drácula* (Bram Stoker), *Las amistades peligrosas* (Choderlos de Laclos), *Pepita Jiménez* (Juan Valera), *Cartas marruecas* (José Cadalso).' },
  { key:'fluxo-consciencia', name:'Flujo de conciencia',
    desc:'La narración imita el fluir continuo de pensamientos, sensaciones y recuerdos de un personaje, a menudo sin orden lógico ni puntuación convencional.',
    forces:'Máxima profundidad psicológica; el tiempo interior se impone al cronológico.',
    risks:'Exige mucho al lector; la trama y la claridad pueden diluirse.',
    examples:'*La señora Dalloway* (Virginia Woolf), *Ulises* (James Joyce), *Cinco horas con Mario* (Miguel Delibes), *Tiempo de silencio* (Luis Martín-Santos).' },
  { key:'primeira-plural', name:'Narrador en primera persona del plural («nosotros»)',
    desc:'Quien cuenta es un grupo —un pueblo, una clase, una generación— que habla con una sola voz y observa a alguien desde fuera.',
    forces:'Da voz a una comunidad, con sus chismes y su culpa compartida; crea un efecto de coro y de leyenda.',
    risks:'El «nosotros» no tiene cuerpo ni escenas propias; es difícil de sostener más allá del cuento o la novela corta.',
    examples:'*Las vírgenes suicidas* (Jeffrey Eugenides), *Una rosa para Emily* (William Faulkner).' },
  { key:'intruso', name:'Narrador intruso',
    desc:'Un narrador que interrumpe la historia para comentarla, opinar, divagar y conversar con el lector.',
    forces:'Voz con personalidad, humor y complicidad; permite ironía, juicios y saltos en el tiempo con total libertad.',
    risks:'Rompe la inmersión; si el comentario vale menos que la historia, el lector se impacienta.',
    examples:'*Don Quijote de la Mancha* (Miguel de Cervantes), *Niebla* (Miguel de Unamuno), *Tom Jones* (Henry Fielding).' }
);

/* ============ SECCIÓN: NARRADOR ============ */
(() => {
  const CONCEPTOS_NARRADOR = [
    { n:'Autor, narrador y narratario', a:'Instancias de la narración',
      d:'El autor es la persona real que escribe; el narrador es la voz inventada que cuenta; el narratario es el destinatario al que esa voz se dirige dentro del texto (el «lector amigo», el destinatario de una carta, un juez, un nieto).',
      u:'Decida a quién habla el narrador y por qué: eso justifica el tono, lo que se explica y lo que se calla. Un narrador que se confiesa ante un cura no cuenta la historia como quien declara ante un tribunal.',
      c:'Confundir autor y narrador produce narradores sin personalidad, o lectores que atribuyen al autor las opiniones del personaje.',
      x:['*Lazarillo de Tormes*: Lázaro escribe a «Vuestra Merced», que le ha pedido que relate «el caso».', '*La familia de Pascual Duarte* (Cela): «Yo, señor, no soy malo…» — el «señor» es el narratario.', '*Lolita* (Nabokov): Humbert se dirige a las «señoras y señores del jurado».', '*Las mil y una noches*: Sherezade cuenta al sultán, y el narratario decide si ella vive.'],
      s:['Narrador no fiable', 'Narración epistolar o documental', 'Voz narrativa'] },
    { n:'Posición del narrador respecto a la historia', a:'Heterodiegético · homodiegético · autodiegético (Genette) · narrador externo e interno',
      d:'Heterodiegético (o externo): el narrador no participa en la historia que cuenta. Homodiegético: participa como personaje secundario o testigo. Autodiegético: es el protagonista de la historia que cuenta. En la enseñanza española se habla también, más simplemente, de narrador externo (tercera persona) e interno (primera persona).',
      u:'Sirve para decidir la legitimidad de la voz: ¿de dónde le viene el conocimiento de lo que cuenta? Un narrador que participó solo sabe lo que vio, oyó o le contaron.',
      c:'No confundir con la persona gramatical: un narrador heterodiegético puede decir «yo» para comentar sin entrar nunca en la acción, como el de *Don Quijote*.',
      x:['Heterodiegético: *La Regenta* (Clarín).', 'Homodiegético: Watson en las historias de Sherlock Holmes; el narrador que reconstruye el crimen en *Crónica de una muerte anunciada*.', 'Autodiegético: *Lazarillo de Tormes*; *Nada* (Carmen Laforet).'],
      s:['Narrador protagonista', 'Narrador testigo', 'Focalización'] },
    { n:'Focalización', a:'Punto de vista · perspectiva narrativa',
      d:'Responde a la pregunta «¿quién ve?», distinta de «¿quién habla?». Cero u omnisciente: el narrador sabe más que cualquier personaje. Interna: la información pasa por el filtro de un personaje —fija (siempre el mismo), variable (cambia entre partes) o múltiple (el mismo suceso visto por varios)—. Externa: el narrador sabe menos que los personajes y solo registra lo visible.',
      u:'Elija la focalización escena a escena según lo que el lector deba saber y sentir. La interna da intimidad; la externa, misterio; la omnisciente, amplitud e ironía.',
      c:'Cambiar de focalización sin intención ni señal clara desorienta al lector.',
      x:['Omnisciente: *Guerra y paz* (Tolstói); *Fortunata y Jacinta* (Galdós).', 'Interna fija: *El proceso* (Kafka), pegado a Josef K.', 'Interna múltiple: *Rashomon* (Kurosawa), el mismo crimen en versiones incompatibles.', 'Externa: *El Jarama* (Sánchez Ferlosio); *Los asesinos* (Hemingway).'],
      t:'Cada Escena tiene un Personaje POV: es la focalización interna de esa Escena. En la ficha del Personaje se ve en qué Escenas es él el punto de vista.',
      s:['Narrador equisciente (tercera persona limitada)', 'Narrador omnisciente', 'Narrador objetivo (cámara)', 'Saltos de punto de vista', 'Efecto Rashomon'] },
    { n:'Personaje POV', a:'Personaje focal · personaje punto de vista',
      d:'El personaje a través de cuyos sentidos y pensamientos el lector vive una escena. Solo se narra lo que él percibe, sabe, recuerda o supone.',
      u:'Regla práctica para elegir el POV de una escena: quien más tiene que perder, quien menos sabe (para crear suspense) o quien va a cambiar. Dé a cada POV un vocabulario y unas obsesiones propios.',
      c:'Demasiados POV diluyen el vínculo del lector; cada nuevo punto de vista debe aportar algo que ningún otro pueda dar.',
      x:['*Canción de hielo y fuego* (George R. R. Martin): un POV por capítulo, con el nombre del personaje en el título.', '*La señora Dalloway* (Woolf): la perspectiva se desliza de mente en mente por las calles de Londres.', '*La casa de los espíritus* (Isabel Allende): la voz de Esteban Trueba irrumpe en primera persona entre capítulos en tercera.'],
      t:'Defina el POV en la ficha de cada Escena; los Personajes POV aparecen señalados en las listas.',
      s:['Focalización', 'Narración polifónica (varios narradores)', 'Saltos de punto de vista'] },
    { n:'Distancia narrativa', a:'Distancia psíquica (John Gardner)',
      d:'El grado de cercanía entre el lector y la conciencia del personaje, del plano general al primer plano interior. El mismo momento puede narrarse desde muy lejos o desde dentro de la cabeza del personaje.',
      u:'Mueva la distancia como una cámara: aléjese para situar y resumir, acérquese en los momentos de emoción. Cambie de forma gradual, no a saltos.',
      c:'Pasar de muy lejos a muy cerca en la misma frase suena a error; una distancia siempre igual vuelve el texto monótono.',
      x:['Lejos: «Era el invierno de 1853. Un hombre alto salió a la calle.»', 'Más cerca: «Enrique detestaba las nevadas.»', 'Dentro: «Dios, cómo odiaba aquella maldita nieve.»', 'Flujo: «Nieve. Por el cuello, dentro de los zapatos, helándole el alma miserable.»'],
      s:['Estilo indirecto libre', 'Monólogo interior', 'Flujo de conciencia'] },
    { n:'Tiempo de la narración', a:'Narración ulterior · simultánea · anterior · intercalada',
      d:'La posición temporal del narrador respecto a lo que cuenta. Ulterior: cuenta después de que ocurra (en pasado, el modo más común). Simultánea: cuenta mientras ocurre (en presente). Anterior: anuncia lo que va a ocurrir (profecías, sueños, predicciones). Intercalada: cuenta por entregas, entre los acontecimientos (diarios, cartas).',
      u:'El pasado da perspectiva y permite al narrador conocer el final; el presente da urgencia e incertidumbre. En la narración intercalada, el narrador no sabe qué viene después, lo que crea un suspense genuino.',
      c:'El presente cansa en textos largos y dificulta el sumario; alternar tiempos sin criterio parece descuido.',
      x:['Ulterior: *Grandes esperanzas* — Pip adulto recuerda a Pip niño.', 'Simultánea: *Los juegos del hambre* (Suzanne Collins).', 'Anterior: los pergaminos de Melquíades en *Cien años de soledad*, que contenían la historia de la familia escrita con cien años de antelación.', 'Intercalada: *Drácula* (Stoker); *Diario de Ana Frank*.'],
      s:['Narración epistolar o documental', 'Prolepsis', 'Tiempos verbales de la narración'] },
    { n:'Voz narrativa', a:'La personalidad de quien cuenta',
      d:'La personalidad audible de quien cuenta: vocabulario, ritmo, humor, aquello en lo que se fija y aquello que omite. Es lo que permite reconocer a un narrador en una sola frase.',
      u:'Defina tres cosas: cómo habla (registro y ritmo), en qué se fija (obsesiones) y qué piensa de sí mismo (ilusiones). Lea en voz alta: la voz se oye.',
      c:'Una voz fuerte no es un exceso de tics; una muletilla repetida en cada párrafo agota.',
      x:['Lázaro de Tormes: humilde en apariencia, socarrón y calculador en cada línea.', 'Holden Caulfield en *El guardián entre el centeno*: jerga adolescente, digresiones, desprecio por los «falsos».', 'Brás Cubas en *Memorias póstumas de Blas Cubas* (Machado de Assis): un difunto irónico y ocioso.'],
      s:['Registro lingüístico', 'Tono', 'Idiolecto y marcas de oralidad'] },
    { n:'Saltos de punto de vista', a:'Head-hopping · cambio de cabeza',
      d:'Cambio brusco y no señalado del punto de vista de un personaje al de otro dentro de la misma escena. Es distinto de la omnisciencia controlada, en la que el narrador tiene voz propia y conduce al lector de mente en mente.',
      u:'En tercera persona limitada, mantenga un POV por escena y cámbielo solo en un corte de Escena o de Capítulo. Si necesita el pensamiento de otro personaje, muéstrelo mediante gestos y palabras.',
      c:'No todo cambio es error: Woolf y Tolstói lo hacen con transiciones cuidadas. El problema es el salto que el lector no puede seguir.',
      x:['Problema: «Ana sonrió, segura de haberlo engañado. Rubén, sin embargo, ya lo había entendido todo y planeaba su venganza.»', 'Solución: «Ana sonrió, segura de haberlo engañado. Rubén le devolvió la sonrisa, demasiado despacio.»'],
      s:['Personaje POV', 'Narrador equisciente (tercera persona limitada)', 'Subtexto'] }
  ];

  SUPPORT.push({ key:'narrador', name:'Tipos de narrador', kicker:'Narrador',
    intro:'Quién cuenta la historia y desde dónde la ve. Es la primera gran decisión de un libro, porque determina lo que el lector puede saber, de quién se siente cerca y en quién confía. Los tipos de abajo pueden elegirse en la ficha de cada Tomo; los conceptos ayudan a afinar la elección.',
    groups:[
      { name:'Tipos de narrador', items:NARRATORS.map(n => ({ n:n.name, d:n.desc, f:n.forces, c:n.risks, x:[n.examples] })) },
      { name:'Conceptos de voz y punto de vista', items:CONCEPTOS_NARRADOR }
    ]});
})();

/* ============ FIGURAS RETÓRICAS ============ */
SUPPORT.push({ key:'figuras', name:'Figuras retóricas', kicker:'Figura',
  intro:'Se llaman también figuras literarias, figuras de estilo o recursos literarios. Son desvíos deliberados del uso corriente de la lengua —en el sonido, en la construcción de la frase o en el sentido de las palabras— para decir más, con más fuerza o con más belleza. La tradición escolar española suele agruparlas en figuras fónicas, sintácticas (o de repetición y de orden), semánticas (tropos) y de pensamiento; aquí se siguen esos grupos. Una figura solo vale cuando hace ver o sentir algo que la frase directa no lograría.',
  groups:[
  { name:'Figuras fónicas', items:[
    { n:'Aliteración', d:'Repetición de uno o varios sonidos, sobre todo consonánticos, en palabras próximas.',
      u:'Use las consonantes para sugerir lo que describe: sibilantes (s, z) para el viento, el susurro o el secreto; oclusivas (p, t, k, b, d) para golpes; líquidas (l, r) para lo que fluye; la erre vibrante para el ruido y la aspereza.',
      c:'En prosa, más de tres o cuatro palabras seguidas suena a trabalenguas; y la aliteración involuntaria («sus suaves sábanas sucias») es un descuido que solo se detecta leyendo en voz alta.',
      x:['«En el silencio solo se escuchaba / un susurro de abejas que sonaba» (Garcilaso de la Vega, *Égloga III*).', '«Bajo el ala aleve del leve abanico» (Rubén Darío, «Era un aire suave»).', '«Ya se oyen los claros clarines» (Rubén Darío, «Marcha triunfal»).', '«Tres tristes tigres tragaban trigo en un trigal» (trabalenguas popular).'],
      s:['Asonancia', 'Onomatopeya', 'Ritmo de la frase'] },
    { n:'Asonancia', a:'Rima asonante · eco vocálico',
      d:'En español, la palabra designa ante todo la rima asonante, en la que solo coinciden las vocales desde la última tónica (*cama* / *playa*), la del romancero y de buena parte de la poesía popular. Por extensión, la repetición de sonidos vocálicos en palabras próximas.',
      u:'Las vocales abiertas (a, e, o) dan claridad y amplitud; las cerradas (i, u) y las secuencias oscuras (o, u) dan sombra, peso y lentitud. En prosa, la asonancia funciona como un eco que une frases o cierra un párrafo con música de copla.',
      c:'En prosa, las rimas y asonancias involuntarias al final de frases seguidas («la situación de la población tras la inundación») son un defecto clásico que hay que corregir.',
      x:['«Verde que te quiero verde. / Verde viento. Verdes ramas» (Federico García Lorca, «Romance sonámbulo»), con rima en á-a a lo largo de todo el poema.', '«Un sonido largo, hondo, ronco, subía del pozo.»'],
      s:['Aliteración', 'Ritmo de la frase', 'Eufonía y cacofonía'] },
    { n:'Onomatopeya', d:'Palabra o secuencia de sonidos que imita el ruido de aquello que designa.',
      u:'Además de las interjecciones (¡zas!, ¡pum!, tictac, din don, quiquiriquí), prefiera los verbos onomatopéyicos, que se integran en la frase: susurrar, chirriar, tintinear, retumbar, zumbar, crujir, chasquear, borbotar.',
      c:'Las onomatopeyas en bruto tienen un efecto infantil o de cómic, lo cual es perfecto cuando se busca precisamente eso. Ojo: varían entre países (el gallo dice «quiquiriquí» en España y en buena parte de América, pero el perro «guau» aquí y «jau» en algunas zonas del Caribe).',
      x:['«En el silencio solo se escuchaba / un susurro de abejas que sonaba» (Garcilaso): la «s» imita el zumbido.', '«El tictac del reloj llenaba la sala.»', '«Las llaves tintinearon en el bolsillo.»'],
      s:['Aliteración', 'Imágenes sensoriales', 'Jitanjáfora'] },
    { n:'Paronomasia', a:'Juego de parónimos',
      d:'Aproximación de palabras de sonido parecido y significado distinto.',
      u:'Funciona en títulos, máximas, refranes, humor y en las réplicas de personajes ingeniosos. Fija la idea en la memoria por el sonido.',
      x:['«Allá van leyes do quieren reyes» (refrán).', '«Del dicho al hecho hay mucho trecho» (refrán).', '«Traduttore, traditore»: traductor, traidor (proverbio italiano).'],
      s:['Dilogía', 'Calambur', 'Aliteración'] },
    { n:'Jitanjáfora', a:'Palabras inventadas por su pura sonoridad',
      d:'Enunciado formado por palabras inexistentes o combinadas sin sentido lógico, que valen solo por su sonido y su ritmo. El término lo acuñó Alfonso Reyes a partir de un poema del cubano Mariano Brull, en el que aparecía la palabra «jitanjáfora».',
      u:'Sirve para juegos, canciones infantiles, conjuros, lenguas inventadas y escenas de amor o delirio en las que el sentido importa menos que la música. Funciona mejor cuando el lector intuye el significado por el sonido.',
      c:'Más allá de unas líneas, agota. Necesita un marco (un juego, una canción, una lengua secreta) que la justifique dentro de la historia.',
      x:['El «glíglico» del capítulo 68 de *Rayuela* (Cortázar): «Apenas él le amalaba el noema…».', 'Las retahílas infantiles: «Pito, pito, gorgorito…».', 'Los conjuros y lenguas inventadas de la fantasía.'],
      s:['Onomatopeya', 'Neologismo'] }
  ]},
  { name:'Figuras de repetición', items:[
    { n:'Anáfora', d:'Repetición de la misma palabra o expresión al comienzo de frases o versos sucesivos.',
      u:'Crea insistencia, ritmo de letanía, crescendo emocional. Buena para discursos, enumeraciones de pérdidas y obsesiones de un personaje.',
      c:'Tras tres o cuatro repeticiones, rompa el patrón: es la ruptura la que da el golpe.',
      x:['«Temprano levantó la muerte el vuelo, / temprano madrugó la madrugada, / temprano estás rodando por el suelo» (Miguel Hernández, «Elegía»).', '«Era el mejor de los tiempos, era el peor de los tiempos» (Dickens, *Historia de dos ciudades*).'],
      s:['Epífora', 'Paralelismo', 'Regla de tres'] },
    { n:'Epífora', a:'Conversión · epístrofe',
      d:'Repetición de la misma palabra o expresión al final de frases o versos sucesivos.',
      u:'El final de la frase es el lugar de mayor peso: repetir ahí martillea una idea fija.',
      x:['«Quería la casa. Soñaba con la casa. Habría matado por la casa.»', '«No lo dijo entonces. No lo dijo nunca. Ya no lo dirá nunca.»'],
      s:['Anáfora', 'Anadiplosis', 'Epanadiplosis'] },
    { n:'Anadiplosis', d:'Repetición, al comienzo de una frase o verso, de la palabra con que terminaba el anterior.',
      u:'Crea encadenamiento: de causas, de pensamientos, de peldaños. Buena para razonamientos obsesivos o para una sensación de fatalidad.',
      x:['«El miedo lleva a la ira, la ira lleva al odio, el odio lleva al sufrimiento» (Yoda, *La amenaza fantasma*).', '«Abrió la puerta. La puerta daba a un pasillo. El pasillo no tenía fin.»'],
      s:['Concatenación', 'Epífora', 'Gradación'] },
    { n:'Concatenación', a:'Anadiplosis en cadena',
      d:'Serie de anadiplosis seguidas: cada miembro empieza con la palabra que cerró el anterior, formando una cadena.',
      u:'Da sensación de avance inevitable, de lógica que arrastra. Muy útil en canciones, cuentos acumulativos y en la voz de personajes que razonan en espiral.',
      c:'Si la cadena es muy larga, el lector deja de oír las palabras y solo oye el mecanismo.',
      x:['«Todo pasa y todo queda, / pero lo nuestro es pasar, / pasar haciendo caminos, / caminos sobre la mar» (Antonio Machado).', 'Los cuentos acumulativos: «el palo que pegó al perro que mordió al gato que se comió al ratón…».'],
      s:['Anadiplosis', 'Gradación', 'Repetición y estribillo'] },
    { n:'Epanadiplosis', d:'Repetición, al final de una frase o verso, de la misma palabra con que empezó.',
      u:'Cierra la frase sobre sí misma, como un círculo: da sensación de obsesión, de clausura o de conjuro.',
      x:['«Verde que te quiero verde» (García Lorca, «Romance sonámbulo»).', '«Nada le importaba ya, nada.»'],
      s:['Anáfora', 'Epífora', 'Estructura circular'] },
    { n:'Políptoton y derivación', a:'Juego de formas de una misma palabra',
      d:'Políptoton: repetición de una palabra con distintos morfemas flexivos (vivo, vivir, viviré). Derivación: repetición de palabras de la misma raíz (amor, amante, amar, enamorado).',
      u:'Hace girar una idea sobre sí misma y le da densidad conceptual. Muy propio de la mística y del Barroco, y eficaz en máximas, conjuros y diálogos ingeniosos.',
      c:'Mal dosificado, parece un ejercicio de conjugación.',
      x:['«Vivo sin vivir en mí, / y tan alta vida espero, / que muero porque no muero» (Teresa de Jesús).', '«Quien parte y reparte se queda con la mejor parte» (refrán).'],
      s:['Paradoja', 'Barroco: culteranismo y conceptismo', 'Retruécano'] },
    { n:'Pleonasmo', a:'Redundancia expresiva',
      d:'Repetición de una idea ya contenida en otra palabra, para reforzarla.',
      u:'El pleonasmo literario intensifica («lo vi con mis propios ojos», «temprano madrugó la madrugada»).',
      c:'El vicioso es solo redundancia: «subir arriba», «bajar abajo», «volver a repetir», «hace años atrás», «erario público», «mendrugo de pan».',
      x:['«Temprano madrugó la madrugada» (Miguel Hernández, «Elegía»).', '«Lo vi, lo vi yo, con estos ojos que se ha de comer la tierra» (fórmula popular).'],
      s:['Hipérbole', 'Repetición y sinónimos'] }
  ]},
  { name:'Figuras de orden y construcción', items:[
    { n:'Paralelismo', d:'Repetición de la misma estructura sintáctica en frases o segmentos sucesivos.',
      u:'Ordena las ideas en pares y series, hace memorables las frases y prepara el contraste: tras dos miembros iguales, el tercero puede sorprender.',
      x:['«Por una mirada, un mundo; / por una sonrisa, un cielo; / por un beso… ¡yo no sé / qué te diera por un beso!» (Gustavo Adolfo Bécquer, *Rima XXIII*).', '«Todas las familias felices se parecen; cada familia infeliz lo es a su manera» (Tolstói, *Ana Karénina*).'],
      s:['Anáfora', 'Antítesis', 'Quiasmo', 'Bimembración', 'Regla de tres'] },
    { n:'Quiasmo', d:'Repetición de dos elementos en orden inverso, en cruz (A-B / B-A).',
      u:'Da aire de sentencia cerrada; perfecto para máximas, dilemas y réplicas finales.',
      c:'Es una figura muy visible: una por capítulo ya es mucho.',
      x:['«Cuando quiero llorar, no lloro… / y a veces lloro sin querer» (Rubén Darío, «Canción de otoño en primavera»).', '«Ni son todos los que están, ni están todos los que son» (dicho popular).', '«Uno para todos y todos para uno» (Dumas, *Los tres mosqueteros*).'],
      s:['Retruécano', 'Paralelismo', 'Antítesis'] },
    { n:'Retruécano', a:'Conmutación',
      d:'Variante del quiasmo, muy apreciada en la tradición española: se repiten las mismas palabras en orden invertido, de modo que el sentido de la segunda frase contrasta con el de la primera o la corrige.',
      u:'Es la figura del ingenio barroco y de la réplica brillante: sirve para cerrar una discusión, desarmar a un rival o condensar una paradoja moral.',
      c:'Si el contraste de sentido no es real, se queda en juego vacío.',
      x:['«¿O cuál es más de culpar, / aunque cualquiera mal haga: / la que peca por la paga / o el que paga por pecar?» (Sor Juana Inés de la Cruz, «Hombres necios»).', '«¿Hay que comer para vivir o vivir para comer?»'],
      s:['Quiasmo', 'Políptoton y derivación', 'Barroco: culteranismo y conceptismo'] },
    { n:'Asíndeton', d:'Supresión de las conjunciones entre palabras o frases coordinadas.',
      u:'Acelera: acciones rápidas, enumeraciones secas, pánico, eficacia. También da sensación de lista inacabada.',
      x:['«Desmayarse, atreverse, estar furioso, / áspero, tierno, liberal, esquivo» (Lope de Vega, soneto «Desmayarse, atreverse…»).', '«Vine, vi, vencí» (Julio César).', '«Corrió, tropezó, cayó, se levantó.»'],
      s:['Polisíndeton', 'Parataxis e hipotaxis', 'Ritmo de la frase'] },
    { n:'Polisíndeton', d:'Repetición insistente de la misma conjunción (casi siempre «y» o «ni»).',
      u:'Ralentiza y acumula: cansancio, abundancia, habla infantil, tono bíblico o solemne.',
      x:['«…el carro y el caballo y caballero» (Fernando de Herrera, «Canción por la victoria de Lepanto»).', '«Y llueve, y sopla el viento, y truena, y la casa cruje, y nadie viene.»', '«No tenía casa, ni pan, ni nombre, ni quien lo llorase.»'],
      s:['Asíndeton', 'Enumeración'] },
    { n:'Elipsis (figura)', d:'Omisión de una o varias palabras que el contexto permite sobrentender.',
      u:'Condensa y da naturalidad, sobre todo en el diálogo: nadie habla con frases completas.',
      x:['«Lo bueno, si breve, dos veces bueno» (Baltasar Gracián, *Oráculo manual*).', '«—¿Café? —Solo, sin azúcar.»', '«En la sala, apenas dos o tres invitados.» (se sobrentiende «había»)'],
      s:['Zeugma', 'Elipsis narrativa', 'Frase nominal'] },
    { n:'Zeugma', d:'Un mismo término (por lo general, el verbo) sirve a varias frases, pero solo aparece en una. Cuando une un sentido literal y uno figurado, produce humor.',
      u:'El zeugma que mezcla planos es un arma clásica de la ironía.',
      x:['«Por ti la verde hierba, el fresco viento, / el blanco lirio y colorada rosa / y dulce primavera deseaba» (Garcilaso, *Égloga I*).', '«Perdió el sombrero y la paciencia.»', '«Salió de casa con el paraguas y un mal presentimiento.»'],
      s:['Elipsis (figura)', 'Ironía'] },
    { n:'Hipérbaton', a:'Inversión · anástrofe (inversión de palabras contiguas)',
      d:'Alteración del orden habitual de las palabras en la frase.',
      u:'Destaca lo que pasa al principio o al final de la frase y da un tono solemne o antiguo. Útil para voces de época, profecías, narradores épicos o personajes que hablan «raro».',
      c:'En exceso convierte la frase en un acertijo. Recuerde que el español admite mucha libertad de orden: el hipérbaton empieza donde el orden choca.',
      x:['«Del salón en el ángulo oscuro, / de su dueño tal vez olvidada, / silenciosa y cubierta de polvo, / veíase el arpa» (Bécquer, *Rima VII*).', '«Era del año la estación florida» (Luis de Góngora, *Soledades*).', '«Larga fue la noche.» / «Del miedo, nada decía.»', 'Yoda: «Mucho que aprender tienes todavía.»'],
      s:['Tono', 'Arcaísmo', 'Barroco: culteranismo y conceptismo'] },
    { n:'Anacoluto', d:'Ruptura de la construcción sintáctica: se empieza la frase de un modo y se termina de otro, como en el habla espontánea.',
      u:'Imita la oralidad, la vacilación y la emoción. Muy útil en diálogos, monólogos interiores y narradores populares.',
      x:['«El que a buen árbol se arrima, buena sombra le cobija» (refrán).', '«Yo, lo que me pasa es que no duermo.»', '«Mi abuelo, nadie le llevaba la contraria.»'],
      s:['Idiolecto y marcas de oralidad', 'Monólogo interior', 'Estilo oral'] },
    { n:'Enumeración', a:'Acumulación · enumeración caótica',
      d:'Presentación sucesiva de varios elementos. Se llama caótica cuando junta cosas de naturaleza muy distinta.',
      u:'Un inventario caracteriza deprisa: lo que hay en un cajón, una maleta o una mesilla de noche dice quién es su dueño. Ponga el elemento más fuerte al final.',
      x:['*El Aleph* (Borges): una enumeración vertiginosa de todo lo que el narrador ve, «el populoso mar», «el alba y la tarde»…', '«En la maleta llevaba dos camisas, un rosario, la foto de su madre y una navaja.»', '«Había de todo en aquel mercado: gallinas, radios, santos de barro, promesas, dientes de oro.»'],
      s:['Gradación', 'Detalle significativo', 'Polisíndeton', 'Asíndeton'] },
    { n:'Gradación', a:'Clímax (ascendente) · anticlímax (descendente)',
      d:'Serie de palabras o ideas ordenadas de menor a mayor intensidad, o al revés.',
      u:'La ascendente construye emoción; la descendente la vacía, y el anticlímax súbito es un mecanismo de humor.',
      x:['«…en tierra, en humo, en polvo, en sombra, en nada» (Góngora, soneto «Mientras por competir con tu cabello»).', '«Un murmullo, un grito, un clamor.»', 'Anticlímax: «Perdió a su mujer, su fortuna, su honra y las llaves del coche.»'],
      s:['Enumeración', 'Regla de tres', 'Hipérbole', 'Concatenación'] },
    { n:'Bimembración', a:'Verso o frase bimembre · plurimembración',
      d:'Frase o verso dividido en dos miembros equilibrados, a menudo simétricos (sustantivo y adjetivo, o dos sintagmas paralelos). La plurimembración extiende el principio a tres o más miembros. Dámaso Alonso la estudió como rasgo central del estilo de Garcilaso y Góngora.',
      u:'Da equilibrio, serenidad y cadencia clásica. En prosa sirve para cerrar párrafos con aire de sentencia o para dar empaque a una voz culta.',
      c:'Sistemática, produce una prosa de prospecto turístico («tierra de contrastes, cuna de la cultura»).',
      x:['«el blanco lirio y colorada rosa» (Garcilaso, *Égloga I*).', '«Corrientes aguas, puras, cristalinas» (Garcilaso, *Égloga I*): plurimembración.', '«Pobre de dinero, rico de paciencia.»'],
      s:['Paralelismo', 'Correlación', 'Epíteto'] },
    { n:'Correlación', a:'Plurimembración correlativa (Dámaso Alonso)',
      d:'Disposición en la que los elementos de una serie se corresponden, uno a uno, con los de otra u otras series: el primero con el primero, el segundo con el segundo, etc.',
      u:'Crea una arquitectura que el lector reconstruye con placer; es muy barroca, pero en prosa moderna funciona a pequeña escala, en descripciones simétricas o en retratos de dos personajes opuestos.',
      c:'Si el lector tiene que volver atrás para emparejar, la figura se convierte en un ejercicio.',
      x:['«El sol y la luna, de día y de noche, alumbran y velan.» (sol–día–alumbra; luna–noche–vela)', 'Los sonetos correlativos de Lope de Vega y Góngora, cuyas series se recogen en el último verso.'],
      s:['Diseminación y recolección', 'Bimembración', 'Paralelismo'] },
    { n:'Diseminación y recolección', d:'Se presentan varios elementos dispersos a lo largo de un texto y, al final, se recogen todos juntos en un solo verso o frase.',
      u:'Es un cierre muy eficaz: la recolección final suena a balance, a sentencia, a destino. En prosa puede cerrar un capítulo retomando los objetos o las personas que se han ido mostrando.',
      x:['Góngora, «Mientras por competir con tu cabello»: describe cabello, frente, labio y cuello y los recoge en «goza cuello, cabello, labio y frente».', '«La casa, el perro, el huerto, el nombre: lo perdió todo en un invierno.»'],
      s:['Correlación', 'Gradación', 'Última frase'] }
  ]},
  { name:'Figuras semánticas (tropos)', items:[
    { n:'Comparación', a:'Símil',
      d:'Relación entre dos realidades mediante un nexo comparativo (como, cual, igual que, parecía, semejante a).',
      u:'La mejor comparación sale del mundo del personaje: un pescador compara con el mar; una cirujana, con el quirófano. Así la imagen, además, caracteriza.',
      c:'Huya de las hechas («blanco como la nieve», «frío como el hielo», «fuerte como un roble»): no hacen ver nada.',
      x:['«Me gustas cuando callas porque estás como ausente» (Pablo Neruda, *Poema 15*).', '«¡Cuánta nota dormía en sus cuerdas, / como el pájaro duerme en las ramas…!» (Bécquer, *Rima VII*).', '«El silencio cayó sobre la mesa como un mantel mojado.»'],
      s:['Metáfora', 'Imágenes sensoriales', 'Lugar común'] },
    { n:'Metáfora', a:'Pura · impura · aposicional · de complemento preposicional',
      d:'Identificación de una realidad con otra con la que guarda semejanza, sin nexo comparativo: una cosa no es «como» la otra, es la otra. La tradición escolar española distingue la metáfora impura (A es B: aparecen el término real y el imaginario), la pura (solo aparece el imaginario), la aposicional (A, B) y la de complemento preposicional (B de A: «el pájaro de tu voz»).',
      u:'Una buena metáfora es concreta, sensorial y sorprendente, pero justa. Puede prolongarse a lo largo de un párrafo (metáfora continuada) u organizar un libro entero.',
      c:'Las metáforas mixtas («el barco del Estado ha descarrilado») y las muertas («un mar de gente») debilitan la prosa.',
      x:['Impura: «Nuestras vidas son los ríos / que van a dar en la mar, / que es el morir» (Jorge Manrique, *Coplas por la muerte de su padre*).', 'Pura: «las perlas de tu boca» (los dientes), en la poesía del Siglo de Oro.', 'Continuada: «La memoria es un desván: solo se sube a buscar otra cosa.»'],
      s:['Comparación', 'Alegoría', 'Símbolo', 'Catacresis', 'Greguería'] },
    { n:'Alegoría', d:'Metáfora desarrollada a lo largo de todo un texto: una historia concreta que representa, punto por punto, una realidad abstracta (moral, política o religiosa).',
      u:'Permite hablar del presente sin nombrarlo (útil bajo censura), dar cuerpo a ideas y crear fábulas. Funciona mejor cuando la historia literal se sostiene sola.',
      c:'Si cada elemento tiene una única lectura evidente, el texto se convierte en acertijo o en sermón.',
      x:['*Coplas por la muerte de su padre* (Manrique): la vida como río y como camino.', '*El gran teatro del mundo* (Calderón): el mundo como escenario y cada vida como un papel.', '*Rebelión en la granja* (Orwell): la granja es la Revolución rusa.', '*Ensayo sobre la ceguera* (Saramago): la ceguera blanca como quiebra moral de una sociedad.'],
      s:['Metáfora', 'Símbolo', 'Personaje tipo'] },
    { n:'Metonimia', d:'Designación de una cosa con el nombre de otra con la que guarda una relación de contigüidad: el autor por la obra, el continente por el contenido, el lugar por la institución, la causa por el efecto, la materia por el objeto, la marca por el producto.',
      u:'Condensa y desplaza la atención al detalle concreto. La descripción realista es, en el fondo, metonímica: muestra la parte palpable de un todo.',
      x:['«Estoy leyendo a Cervantes.» (la obra)', '«Se tomó dos copas.» (el contenido)', '«La Moncloa no ha respondido.» (el Gobierno de España); «La Casa Rosada guarda silencio.» (el de Argentina)', '«Vive del sudor de su frente.» (el trabajo)'],
      s:['Sinécdoque', 'Detalle significativo'] },
    { n:'Sinécdoque', d:'Caso particular de la metonimia: la parte por el todo, el todo por la parte, el singular por el plural, la especie por el género.',
      u:'Muy cinematográfica: filmar a una multitud por los pies, a un ejército por las lanzas, a un personaje por un detalle.',
      x:['«Veinte velas en el horizonte.» (barcos)', '«Tenía cuatro bocas que alimentar.»', '«España ganó por dos a cero.» (la selección)', '«Danos hoy nuestro pan de cada día.» (el alimento)'],
      s:['Metonimia', 'Detalle significativo'] },
    { n:'Personificación', a:'Prosopopeya · animismo',
      d:'Atribución de cualidades, gestos o habla humanos a animales, objetos, fuerzas de la naturaleza o ideas.',
      u:'Da vida al escenario y proyecta en él el estado de ánimo del personaje. En la prosopopeya propiamente dicha, lo inanimado o lo ausente toma la palabra.',
      c:'En exceso, todo se vuelve sentimental.',
      x:['«La luna vino a la fragua / con su polisón de nardos» (García Lorca, «Romance de la luna, luna»).', '«La casa gemía con cada ráfaga.»', '«La muerte llamó a su puerta y él fingió no estar en casa.»'],
      s:['Falacia patética', 'Hipálage', 'Apóstrofe', 'Animalización y cosificación'] },
    { n:'Animalización y cosificación', a:'Degradación · reificación',
      d:'Procedimientos inversos a la personificación: atribuir a una persona rasgos de animal (animalización) o de objeto, máquina o muñeco (cosificación).',
      u:'Son las herramientas de la caricatura, la sátira y lo grotesco: degradan, distancian y hacen reír o estremecer. Valle-Inclán las convirtió en sistema en el esperpento; también sirven para mostrar cómo un personaje ve a otro.',
      c:'Aplicadas al protagonista de forma continua, le quitan humanidad y el lector deja de interesarse por él.',
      x:['El dómine Cabra de *El Buscón* (Quevedo): «clérigo cerbatana, largo solo en el talle».', 'Los personajes de *Luces de bohemia* (Valle-Inclán), que se mueven como fantoches.', '«El jefe ladró una orden y volvió a su cueva de cristal.»'],
      s:['Personificación', 'Caricatura y grotesco', 'Esperpento', 'Retrato'] },
    { n:'Sinestesia', d:'Fusión de sensaciones de sentidos distintos en una misma imagen.',
      u:'Vuelve nuevas e intensas las percepciones; útil para estados alterados, recuerdos de infancia, música, comida o deseo.',
      x:['«El grito deja en el viento / una sombra de ciprés» (García Lorca, *Poema del cante jondo*).', '«La música callada, / la soledad sonora» (San Juan de la Cruz, *Cántico espiritual*).', '«Un amarillo chillón.» / «Una voz áspera y oscura.»'],
      s:['Imágenes sensoriales', 'Hipálage', 'Impresionismo literario'] },
    { n:'Hipálage', a:'Epíteto desplazado',
      d:'Atribución a una palabra de una cualidad que, lógicamente, corresponde a otra de la misma frase.',
      u:'Con un solo adjetivo desplazado se caracteriza a la vez el objeto y a la persona. Fue muy cultivada por el modernismo y por Valle-Inclán.',
      x:['«Fumaba un pensativo cigarrillo.»', '«Subió las escaleras cansadas del edificio.»', '«Bebía su café solitario.»'],
      s:['Adjetivación expresiva', 'Personificación', 'Sinestesia'] },
    { n:'Antonomasia', d:'Sustitución de un nombre propio por una cualidad o un epíteto que lo identifica, o uso de un nombre propio como común.',
      u:'Varía la designación, ensalza o ridiculiza. Los apodos de los personajes son antonomasias, y caracterizan a quien los pone. La literatura española ha regalado varias a la lengua.',
      x:['«El Manco de Lepanto» (Cervantes); «el Fénix de los Ingenios» (Lope de Vega); «el Libertador» (Simón Bolívar).', '«Es un donjuán», «es un quijote», «hizo de celestina», «un lazarillo».'],
      s:['Perífrasis', 'Nombres de los personajes'] },
    { n:'Perífrasis', a:'Circunloquio · rodeo',
      d:'Decir con varias palabras lo que podría decirse con una.',
      u:'Evita repeticiones, ennoblece, suaviza o ironiza. También caracteriza a personajes pomposos, burocráticos o evasivos.',
      c:'Casi siempre la palabra exacta es más fuerte. Y no confundir con la perífrasis verbal de la gramática («voy a salir», «tengo que ir»).',
      x:['«Era del año la estación florida» (Góngora) = la primavera.', '«El astro rey» = el sol; «el país del sol naciente» = Japón.', '«El líquido elemento»: la perífrasis gastada es un tic periodístico que conviene evitar.'],
      s:['Antonomasia', 'Eufemismo', 'Lugar común'] },
    { n:'Símbolo', d:'Objeto, ser, color o gesto concreto que, sin dejar de ser lo que es, adquiere un sentido abstracto más allá del literal.',
      u:'Los símbolos más fuertes nacen dentro de la historia: un objeto corriente que vuelve en momentos decisivos y va acumulando sentido. Preséntelo primero como simple cosa.',
      c:'Explicar el símbolo lo mata. Los universales (paloma, rosa roja, cuervo) están gastados.',
      x:['La luna, el caballo y el cuchillo como anuncios de muerte en la obra de García Lorca.', 'Las mariposas amarillas que siguen a Mauricio Babilonia en *Cien años de soledad*.', 'La luz verde del muelle en *El gran Gatsby*.', 'La caracola en *El señor de las moscas*: el orden y la palabra.'],
      s:['Motivo recurrente', 'Alegoría', 'Correlato objetivo'] },
    { n:'Catacresis', a:'Metáfora lexicalizada',
      d:'Metáfora tan integrada en la lengua que ya no se percibe como figura: es el nombre corriente de las cosas.',
      u:'Puede reanimarse tomándola al pie de la letra: un recurso de humor y de poesía.',
      x:['«Pata de la mesa», «diente de ajo», «brazo de mar», «ojo de la aguja», «boca del metro», «cuello de botella».', 'Reanimada: «La mesa tenía cuatro patas y ninguna gana de andar.»'],
      s:['Metáfora', 'Lugar común'] },
    { n:'Epíteto', a:'Adjetivo explicativo · epíteto épico',
      d:'Adjetivo que destaca una cualidad propia o característica del sustantivo, sin añadir información que lo distinga de otros: «la blanca nieve», «la verde hierba». En la épica, el epíteto es una fórmula fija que acompaña al héroe.',
      u:'En español suele ir antepuesto, y por eso suena valorativo o poético. Úselo para ralentizar, para dar color de época o de leyenda, o con ironía. Los epítetos épicos son eficaces en fantasía y en sagas familiares: la fórmula se vuelve el nombre.',
      c:'El epíteto ornamental que no aporta nada («la fría nieve», «el oscuro abismo») es relleno.',
      x:['«Por ti la verde hierba, el fresco viento…» (Garcilaso, *Égloga I*).', 'En el *Cantar de mio Cid*, el héroe es «el que en buen hora nació» y «el que en buen hora ciñó espada».', '«Aquiles, el de los pies ligeros» (Homero).'],
      s:['Adjetivación expresiva', 'Bimembración', 'Antonomasia'] },
    { n:'Greguería', a:'Humorismo + metáfora (Ramón Gómez de la Serna)',
      d:'Breve frase ingeniosa, inventada por Ramón Gómez de la Serna, que une una metáfora sorprendente y un toque de humor. Él mismo la definió con la fórmula «humorismo + metáfora».',
      u:'Es un buen ejercicio para afinar la mirada y para dar a un narrador o a un personaje una forma de ver el mundo propia. En prosa narrativa, una greguería ocasional ilumina una descripción.',
      c:'Encadenadas, cansan; y la que necesita explicación ha fracasado.',
      x:['«El agua se suelta el pelo en las cascadas» (Ramón Gómez de la Serna).', '«El arco iris es la bufanda del cielo» (atribuida a Ramón Gómez de la Serna).', '«El paraguas es el único árbol que se abre cuando llueve.»'],
      s:['Metáfora', 'Humor y comicidad', 'Extrañamiento'] }
  ]},
  { name:'Figuras de pensamiento', items:[
    { n:'Antítesis', d:'Contraposición de dos palabras o ideas de sentido opuesto.',
      u:'Estructura conflictos, dilemas y retratos (lo que alguien parece / lo que es). El contraste hace más nítido cada polo.',
      x:['«Es tan corto el amor, y es tan largo el olvido» (Pablo Neruda, *Poema 20*).', '«Ayer naciste, y morirás mañana» (Góngora, «A una rosa»).', '«Ser o no ser, esa es la cuestión» (Shakespeare, *Hamlet*).'],
      s:['Oxímoron', 'Paradoja', 'Paralelismo', 'Personaje contraste'] },
    { n:'Oxímoron', d:'Unión, en una misma expresión, de dos términos que se contradicen.',
      u:'Expresa emociones ambivalentes —amor, duelo, deseo, vergüenza— en dos palabras.',
      x:['«Es hielo abrasador, es fuego helado, / es herida que duele y no se siente» (Francisco de Quevedo, «Definición del amor»).', '«La música callada» (San Juan de la Cruz).', '«Silencio ensordecedor», «dulce amargura», «muerto viviente».'],
      s:['Antítesis', 'Paradoja'] },
    { n:'Paradoja', d:'Afirmación que parece contradecir la lógica o el sentido común, pero que encierra una verdad.',
      u:'Buena para temas, máximas de personajes sabios o cínicos y lemas de mundos distópicos.',
      x:['«Vivo sin vivir en mí… / que muero porque no muero» (Teresa de Jesús).', '«Todos los animales son iguales, pero algunos son más iguales que otros» (Orwell, *Rebelión en la granja*).', '«Solo sé que no sé nada» (atribuida a Sócrates).'],
      s:['Oxímoron', 'Antítesis', 'Ironía'] },
    { n:'Ironía', a:'Antífrasis · sarcasmo (la forma agresiva)',
      d:'Decir una cosa para dar a entender otra, normalmente la contraria. Depende de la complicidad con el lector, que debe percibir la distancia entre lo dicho y lo pensado.',
      u:'Distinga la ironía verbal (esta) de la ironía de situación (el resultado contradice la expectativa) y de la ironía dramática (el lector sabe más que el personaje). La ironía del narrador crea distancia crítica: es el arma de Cervantes, de Larra, de Clarín y de Jane Austen.',
      c:'Sin pistas de tono puede leerse al pie de la letra; en dosis continua vuelve antipático al narrador.',
      x:['«¡Pues sí que estamos buenos!» (ante un desastre).', '«Es una verdad universalmente reconocida que un hombre soltero, poseedor de una gran fortuna, necesita una esposa» (Jane Austen, *Orgullo y prejuicio*).', '*Vuelva usted mañana* (Mariano José de Larra): la burocracia española retratada con cortesía envenenada.'],
      s:['Ironía dramática', 'Lítote', 'Tono', 'Humor y comicidad', 'Sátira'] },
    { n:'Hipérbole', d:'Exageración deliberada de la realidad.',
      u:'Propia del habla coloquial, del humor, del registro épico y de los personajes dramáticos. Caracteriza a quien la usa.',
      c:'En un narrador sobrio, una sola exageración desentona.',
      x:['«Érase un hombre a una nariz pegado» (Quevedo, «A una nariz»).', '«Tanto dolor se agolpa en mi costado / que por doler me duele hasta el aliento» (Miguel Hernández, «Elegía»).', '«Te lo he dicho mil veces.»', 'En *Cien años de soledad*, la lluvia dura cuatro años, once meses y dos días.'],
      s:['Lítote', 'Gradación', 'Humor y comicidad', 'Caricatura y grotesco'] },
    { n:'Eufemismo', d:'Sustitución de una palabra o idea desagradable, chocante o tabú por una expresión más suave.',
      u:'Muestra pudor, delicadeza, hipocresía o miedo. Los eufemismos de un personaje, o de un régimen, dicen lo que no se puede decir en ese mundo.',
      x:['«Pasó a mejor vida.» / «Ya no está entre nosotros.»', '«Reajuste de plantilla», «desaceleración económica», «personas de la tercera edad».', '«Daños colaterales»; «solución final»: el eufemismo al servicio del horror.'],
      s:['Disfemismo', 'Perífrasis', 'Lítote', 'Subtexto'] },
    { n:'Disfemismo', d:'Lo contrario del eufemismo: uso de una expresión cruda, grosera o despectiva donde existía una neutra.',
      u:'Da dureza, humor negro, rebeldía. Caracteriza a personajes cínicos, soldados, médicos, sepultureros.',
      x:['«Estiró la pata.» / «La palmó.» / «Se fue al otro barrio.»', '«Ese matasanos.» / «La caja tonta.» (la televisión)', '«Esa cafetera a la que llamas coche.»'],
      s:['Eufemismo', 'Registro lingüístico', 'Tacos e insultos'] },
    { n:'Lítote', a:'Litote · atenuación',
      d:'Afirmación hecha mediante la negación de lo contrario; se dice menos para significar más.',
      u:'Tono contenido, modesto o irónico. Típica de narradores discretos y del humor británico (understatement).',
      x:['«No es ningún tonto.»', '«No fue precisamente el día más feliz de mi vida.»', '«El caballero no es del todo un desconocido para la policía.»'],
      s:['Ironía', 'Eufemismo', 'Hipérbole'] },
    { n:'Apóstrofe', a:'Invocación',
      d:'Interpelación directa a alguien o algo: presente, ausente, muerto o inanimado.',
      u:'Eleva de golpe el tono emocional. También sirve para que el narrador se dirija al lector.',
      x:['«¡Oh noche que guiaste! / ¡Oh noche amable más que la alborada!» (San Juan de la Cruz, «Noche oscura»).', '«Lector, me casé con él» (Charlotte Brontë, *Jane Eyre*).', '«Desocupado lector…» (Cervantes, prólogo del *Quijote*).'],
      s:['Personificación', 'Metaficción', 'Narrador en segunda persona'] },
    { n:'Interrogación retórica', d:'Pregunta que no busca respuesta, sino afirmar con más fuerza, expresar duda o implicar al lector.',
      u:'En el monólogo interior muestra al personaje debatiéndose; en la narración, plantea la pregunta que el lector ya se hacía.',
      c:'Varias seguidas suenan a melodrama.',
      x:['«¿Qué se hizo el rey don Juan? / Los infantes de Aragón / ¿qué se hicieron?» (Manrique, *Coplas*): el tópico del *ubi sunt*.', '«¿Y qué podía haber hecho yo?»'],
      s:['Exclamación retórica', 'Monólogo interior', 'Pregunta dramática'] },
    { n:'Exclamación retórica', a:'Ecfonesis',
      d:'Expresión de una emoción intensa —asombro, dolor, alegría, indignación— en forma exclamativa.',
      u:'Marca los picos emocionales de una voz o de un personaje. En español va entre signos de apertura y cierre (¡…!), que permiten exclamar solo una parte de la frase.',
      c:'Se gasta enseguida: un narrador que exclama a cada página parece histérico o ingenuo. Recuerde no omitir el signo de apertura, error frecuente por influencia del inglés.',
      x:['«¡Cuánta nota dormía en sus cuerdas…!» (Bécquer, *Rima VII*).', '«Y entonces, ¡qué silencio!»'],
      s:['Interrogación retórica', 'Apóstrofe', 'Puntuación expresiva'] },
    { n:'Reticencia', a:'Aposiopesis · suspensión',
      d:'Interrupción de una frase dejando sobrentendido el resto.',
      u:'Vacilación, amenaza velada, emoción que corta la voz, pudor. En el diálogo, lo que se queda sin decir suele ser lo más importante.',
      c:'Los puntos suspensivos son siempre tres; en exceso, ablandan la prosa. A menudo un punto es más fuerte.',
      x:['«Como te vuelva a ver por esta casa…»', '«Dijo que volvería, pero…»'],
      s:['Subtexto', 'Puntuación expresiva'] },
    { n:'Preterición', a:'Paralipsis',
      d:'Fingir que no se va a hablar de algo… mientras se habla de ello.',
      u:'Arma de insinuación: perfecta para personajes manipuladores, políticos, chismosos y narradores poco inocentes.',
      x:['«Y no voy a hablar del dinero que me debes.»', '«No quiero recordarle a nadie dónde estaba él aquella noche.»', 'El discurso de Marco Antonio en *Julio César* (Shakespeare): «Vengo a enterrar a César, no a alabarlo»… y lo alaba.'],
      s:['Ironía', 'Subtexto', 'Narrador no fiable'] },
    { n:'Dilogía', a:'Juego de palabras · equívoco · doble sentido',
      d:'Empleo de una palabra con dos significados a la vez dentro del mismo enunciado. Es el corazón del juego de palabras y del equívoco barroco.',
      u:'Caracteriza a personajes ingeniosos (o insoportables), da títulos y puede esconder pistas a la vista de todos. Quevedo y Gracián son sus maestros.',
      c:'Los juegos de palabras casi nunca se pueden traducir, y algunos son locales: una palabra inocente en un país puede ser grosera en otro.',
      x:['«…porque en las venas de Oriente / todas las sangres son reales» (Quevedo, «Poderoso caballero es don Dinero»): «reales» es regia y es moneda.', '*La importancia de llamarse Ernesto* (Oscar Wilde): en inglés, «Ernest» suena a «earnest», serio.', '«¿El dentista? Un hombre de mucho fondo… de caja.»'],
      s:['Calambur', 'Paronomasia', 'Humor y comicidad', 'Ambigüedad y anfibología'] },
    { n:'Calambur', d:'Reagrupación de las sílabas de una o varias palabras para que signifiquen otra cosa.',
      u:'Es el juego de palabras más sonoro: sirve para adivinanzas, chistes, réplicas ingeniosas y mensajes cifrados dentro de la trama.',
      c:'Solo funciona en voz alta o si el lector lo «oye»; necesita contexto para no pasar inadvertido.',
      x:['«Entre el clavel y la rosa, / su majestad escoja» («su majestad es coja»), anécdota atribuida a Quevedo.', '«Oro parece, / plata no es» (adivinanza popular: el plátano).', '«Yo lo coloco y ella lo quita» / «Yo loco, loco, y ella loquita».'],
      s:['Dilogía', 'Paronomasia', 'Humor y comicidad'] }
  ]}
]});

/* ============ RECURSOS DE ESTILO ============ */
SUPPORT.push({ key:'estilo', name:'Recursos de estilo', kicker:'Estilo',
  intro:'Todo lo que define cómo suena el texto, más allá de las figuras propiamente dichas: la manera de reproducir las voces, la longitud y el ritmo de las frases, la elección de las palabras, el tono, la descripción. Son decisiones de prosa: la misma escena, con los mismos hechos, puede escribirse de cien maneras, y el estilo es la suma de esas elecciones.',
  groups:[
  { name:'Modos del discurso', items:[
    { n:'Estilo directo', a:'Discurso directo',
      d:'Reproducción literal de las palabras de los personajes. En la narrativa en español se marca con raya (—) al comienzo de cada intervención, y las aclaraciones del narrador van también entre rayas; las comillas quedan para citas, pensamientos y palabras reproducidas dentro de otra intervención.',
      u:'Da vida, ritmo y presencia de escena. Prefiera «dijo» y «preguntó», que son invisibles, y sustituya parte de los verbos de habla por gestos. Puntuación según la *Ortografía* académica: «—Ya voy —dijo Marta—. Espera un momento.» El punto va detrás de la raya de cierre, nunca antes.',
      c:'Errores frecuentes: usar guion corto (-) en lugar de raya; poner punto antes del inciso («—Ya voy. —dijo»); cerrar con raya al final del párrafo. Y el diálogo que solo transmite información («Como sabes, Rubén, nuestro padre murió hace diez años…») es exposición disfrazada.',
      x:['«—¿Vienes? —Voy. —¿Cuándo? —Cuando pueda.»', '«—No pienso firmar —dijo el notario, y cerró la carpeta.»', 'En buena parte de América las comillas de uso general son las inglesas (“ ”); la raya del diálogo es la misma en todo el ámbito hispánico.'],
      s:['Estilo indirecto', 'Verbos de habla y acotaciones', 'Subtexto'] },
    { n:'Estilo indirecto', a:'Discurso indirecto',
      d:'El narrador refiere con sus propias palabras lo que dijo el personaje, en una oración subordinada («dijo que…»), con los cambios correspondientes de persona, tiempos verbales y deícticos (hoy → aquel día; aquí → allí; mañana → al día siguiente).',
      u:'Resume conversaciones largas o banales y mantiene el control del narrador. Sirve para pasar deprisa por lo que no merece escena.',
      c:'Cuidado con la correlación de tiempos («Dijo que vendría», no «Dijo que vendrá» si el hecho ya pasó) y con el dequeísmo («Dijo de que…»), incorrecto.',
      x:['«Dijo que vendría al día siguiente, si el tiempo lo permitía.»', 'Directo: «—Vengo mañana.» → Indirecto: «Dijo que venía al día siguiente.»'],
      s:['Estilo directo', 'Estilo indirecto libre', 'Escena y sumario'] },
    { n:'Estilo indirecto libre', a:'Discurso indirecto libre',
      d:'Fusión de la voz del narrador con la del personaje: se mantienen la tercera persona y el pasado, pero la frase recoge las palabras, exclamaciones y dudas del personaje, sin «dijo que» ni «pensó que».',
      u:'Es la herramienta central de la novela moderna en tercera persona limitada: da acceso al pensamiento sin interrumpir la narración. Para reconocerlo: preguntas, exclamaciones y juicios que solo pueden ser del personaje.',
      c:'Si la voz del personaje no se distingue de la del narrador, el efecto se pierde.',
      x:['«Miró el reloj. ¡Medianoche! Y Carlos sin aparecer. ¿Qué diría su madre?»', '*Madame Bovary* (Flaubert) y *Emma* (Austen) son los modelos clásicos.', 'Clarín lo emplea constantemente con Ana Ozores en *La Regenta*; Galdós, en *Fortunata y Jacinta*.'],
      s:['Narrador equisciente (tercera persona limitada)', 'Distancia narrativa', 'Monólogo interior'] },
    { n:'Estilo directo libre', a:'Discurso directo libre',
      d:'Las palabras de los personajes entran en el hilo de la narración sin rayas, comillas ni punto y aparte; a veces solo una coma y una mayúscula marcan el cambio de interlocutor.',
      u:'Crea un flujo oral continuo, en el que narrador y personajes comparten el mismo aliento. Es la firma de José Saramago; en español lo practican, de modos diversos, Juan Rulfo, Juan Goytisolo o Elena Garro.',
      c:'Exige que cada voz se distinga por el contenido y el ritmo. Pide un lector atento.',
      x:['«Preguntó él, Vienes conmigo, y ella respondió, Voy, pero hoy no, Entonces cuándo, Cuando deje de tener miedo.»', '*Ensayo sobre la ceguera* y *Memorial del convento* (Saramago).'],
      s:['Estilo directo', 'Puntuación expresiva', 'Frase larga'] },
    { n:'Verbos de habla y acotaciones', a:'Verbos dicendi · incisos del narrador',
      d:'Las pequeñas indicaciones que acompañan a una intervención: quién la dice («dijo», «preguntó») y qué hace mientras la dice («Dejó la taza.»).',
      u:'«Dijo» es casi invisible: el lector pasa por él sin verlo. Reserve los verbos expresivos (gruñó, suplicó) para cuando la frase no muestre por sí misma el tono. Un gesto en lugar del verbo identifica a quien habla, da cuerpo a la escena y puede desmentir las palabras. Según la *Ortografía*, si el inciso no lleva verbo de habla, la intervención se cierra con punto y el inciso empieza con mayúscula: «—No voy. —Volvió a sentarse.» En intercambios rápidos entre dos personajes, prescinda de todo.',
      c:'El adverbio que explica lo que la frase ya dice («—¡Te odio! —gritó ella furiosamente») es redundante. No se «sonríe» ni se «encoge de hombros» una frase: son gestos, no verbos de habla, y piden punto y mayúscula.',
      x:['Pesado: «—No voy —replicó él obstinadamente.»', 'Ligero: «—No voy. —Volvió a sentarse y abrió el periódico.»', 'Elmore Leonard, en sus diez reglas: no usar nunca otro verbo que «dijo».'],
      s:['Estilo directo', 'Subtexto', 'Verbos precisos', 'Mostrar, no contar'] },
    { n:'Formas de tratamiento', a:'Tú · usted · vos · vosotros · ustedes · don / doña',
      d:'El modo en que los personajes se dirigen unos a otros. El español tiene un sistema rico y muy variable según el país: «tú» (confianza), «usted» (respeto o distancia), «vos» (voseo, la forma de confianza en Argentina, Uruguay, Paraguay, buena parte de Centroamérica y zonas de Colombia, Venezuela o Chile), «vosotros» (plural de confianza solo en España, salvo Canarias y parte de Andalucía occidental) frente a «ustedes» (plural general en América), «don / doña» con el nombre de pila, «señorito», títulos («señor doctor», «licenciado» en México), el ustedeo entre íntimos en Colombia o Costa Rica, «su merced» en zonas de Colombia.',
      u:'Cada pareja de personajes tiene su tratamiento, y dice mucho de edad, clase, afecto y poder. Los momentos en que el tratamiento cambia son escenas: la primera vez que alguien pasa al «tú»; la vuelta helada al «usted» tras una pelea; el hijo que trata de usted a su padre. En España el tuteo se ha extendido mucho desde los años setenta; en muchos países americanos el «usted» sigue siendo habitual con desconocidos y mayores.',
      c:'Las incoherencias de tratamiento se notan enseguida, también las geográficas: un porteño no dice «vosotros» ni «tú tienes», y un madrileño no vosea. En novela histórica, compruebe qué se usaba en la época y el medio («vuestra merced» es el origen de «usted»).',
      x:['Asimetría: el amo tutea a la criada; ella le contesta «sí, señorito».', 'Cambio: «—Tutéame, por favor. —No me sale, don Julián.»', 'Voseo rioplatense: «—¿Vos sabés lo que hiciste? —Sí, y no me arrepiento.»', 'Retorno al usted tras una pelea: «—Como usted diga, señor Ramos.»'],
      t:'Merece la pena anotar, en una Nota asociada a dos Personajes, cómo se tratan entre sí y a partir de qué Escena cambia.',
      s:['Registro lingüístico', 'Idiolecto y marcas de oralidad', 'Regionalismo y variedades del español', 'Subtexto'] }
  ]},
  { name:'Frase y ritmo', items:[
    { n:'Ritmo de la frase', a:'Cadencia · música de la prosa',
      d:'La música de la prosa: la alternancia de frases breves y largas, de sílabas tónicas y átonas, de pausas y aceleraciones.',
      u:'Haga que la forma imite el contenido: frases breves para la acción, el choque y la certeza; largas para la contemplación, la duda y la acumulación. La variación crea la música: después de tres frases largas, una breve suena como un tambor. Lea siempre en voz alta.',
      x:['«Esperó. Nada. Esperó un poco más, contando las gotas que caían del canalón al cubo, y cuando ya se había convencido de que nadie vendría oyó, muy a lo lejos, la verja.»'],
      s:['Frase breve', 'Frase larga', 'Ritmo narrativo', 'Puntuación expresiva'] },
    { n:'Frase breve', a:'Estilo seco · minimalismo',
      d:'Periodos cortos, de sintaxis sencilla, con pocas subordinadas y pocos adjetivos.',
      u:'Tensión, acción, frialdad, impacto. Lo esencial va al final de la frase. Es el estilo de Hemingway, de Raymond Carver, de la novela negra; en español, del Delibes más sobrio o de Juan José Millás.',
      c:'Siempre igual, se vuelve telegráfica y monótona.',
      x:['«Hoy ha muerto mamá» (Albert Camus, *El extranjero*).', '«Abrió la puerta. La habitación estaba vacía. La cama, hecha.»'],
      s:['Frase larga', 'Parataxis e hipotaxis', 'Frase nominal', 'Teoría del iceberg'] },
    { n:'Frase larga', a:'Periodo largo · frase río',
      d:'Periodos extensos, con oraciones encadenadas, incisos y recuperaciones, que pueden prolongarse durante una página.',
      u:'Imita el pensamiento, la memoria, el vértigo, la oralidad torrencial. Dele una columna vertebral (un verbo principal claro, o un «y» que la va arrastrando) y puntos de apoyo para que el lector respire.',
      c:'Sin arquitectura, el lector se pierde, y no vuelve atrás para encontrarse.',
      x:['*El otoño del patriarca* (García Márquez): capítulos enteros casi sin puntos.', 'Proust, Faulkner, Saramago, Javier Marías (*Corazón tan blanco*), Fernando Vallejo, László Krasznahorkai.'],
      s:['Frase breve', 'Flujo de conciencia', 'Estilo directo libre'] },
    { n:'Parataxis e hipotaxis', a:'Coordinación y subordinación',
      d:'Parataxis: oraciones puestas una junto a otra, coordinadas o yuxtapuestas, sin jerarquía («Llegó, se sentó, pidió vino»). Hipotaxis: oraciones subordinadas unas a otras, que explicitan causa, tiempo, condición o concesión («Como había llegado tarde, se sentó sin pedir permiso, aunque sabía…»).',
      u:'La parataxis muestra y deja al lector el trabajo de relacionar: es objetiva, rápida, cinematográfica. La hipotaxis explica y analiza: es el estilo del razonamiento y de la psicología.',
      x:['Parataxis: Hemingway, Cormac McCarthy, la Biblia, el *Cantar de mio Cid*.', 'Hipotaxis: Henry James, Proust, Galdós en los grandes retratos, Javier Marías.'],
      s:['Asíndeton', 'Polisíndeton', 'Frase breve', 'Frase larga'] },
    { n:'Frase nominal', d:'Frase sin verbo conjugado.',
      u:'Fija una imagen como una fotografía o una acotación teatral: buena para abrir escenas, para enumeraciones descriptivas y para el impacto.',
      x:['«Noche. Llovizna. Nadie en la calle.»', '«Un disparo. Después, el silencio.»', 'Las acotaciones de Valle-Inclán: «Hora crepuscular. Un guardillón con ventano angosto.»'],
      s:['Frase breve', 'Elipsis (figura)'] },
    { n:'Regla de tres', a:'Tricolon · enumeración ternaria',
      d:'Series de tres elementos: palabras, frases o acontecimientos. Dos crean un patrón; el tercero lo confirma o lo rompe.',
      u:'En la frase: tres adjetivos, tres verbos, con el más fuerte al final. En el humor: dos normales y uno inesperado. En la trama: tres intentos, tres pruebas, tres hermanos, la estructura de los cuentos tradicionales.',
      x:['«Vine, vi, vencí» (Julio César).', '«Libertad, igualdad, fraternidad.»', 'Humor: «Llevaba todo lo necesario: tienda, linterna y un abogado.»', 'Trama: los tres cerditos; las tres visitas de los espíritus en *Cuento de Navidad* (Dickens).'],
      s:['Gradación', 'Anáfora', 'Ciclos de intento y fracaso'] },
    { n:'Puntuación expresiva', a:'Puntuación como recurso de estilo',
      d:'Uso de la puntuación como recurso de estilo y no solo gramatical: puntos suspensivos, rayas, dos puntos, paréntesis, ausencia de comas, puntos que cortan la frase. El español tiene además los signos dobles de interrogación y exclamación (¿?, ¡!), que permiten marcar solo una parte de la oración.',
      u:'La raya interrumpe y destaca; los dos puntos prometen una revelación; el paréntesis crea un aparte cómplice; el punto a mitad de frase golpea («No. Voy. A salir.»). Los signos de apertura sirven para matizar: «Y tú, ¿qué harías?».',
      c:'El signo de exclamación se gasta pronto: uno por página ya es mucho. Mayúsculas y cursivas para gritar son muletillas. Nunca más de tres puntos suspensivos, ni combinaciones como «!!!» o «?!» en la narración.',
      x:['Saramago: solo comas y puntos, con mayúscula para cada intervención.', 'Cormac McCarthy: sin comillas ni rayas y casi sin comas.', 'Emily Dickinson y sus guiones.'],
      s:['Estilo directo libre', 'Reticencia', 'Ritmo de la frase', 'Exclamación retórica'] },
    { n:'Repetición y estribillo', a:'Leitmotiv verbal',
      d:'Retorno deliberado de una palabra, frase o fórmula a lo largo del texto.',
      u:'Crea cohesión, obsesión y ritmo. Una frase que vuelve en contextos distintos cambia de sentido cada vez y puede cerrar el libro con otro peso.',
      c:'Distíngala de la repetición por descuido: la deliberada tiene que notarse como elección.',
      x:['«Así fue», la fórmula resignada que acompaña cada muerte en *Matadero cinco* (Vonnegut).', '«Nunca más», el estribillo de *El cuervo* (Poe).', '«Preferiría no hacerlo», la respuesta de *Bartleby, el escribiente* (Melville).'],
      s:['Motivo recurrente', 'Anáfora', 'Concatenación'] },
    { n:'Párrafo y espacio en blanco', d:'La división en párrafos, las líneas en blanco y los cortes de sección también son puntuación, a mayor escala.',
      u:'Un párrafo de una sola línea destaca. Una línea en blanco marca un salto de tiempo, de lugar o de punto de vista. Los bloques compactos dan densidad y claustrofobia; mucho blanco da velocidad y aire.',
      x:['Capítulos de una sola frase: «Mi madre es un pez», en *Mientras agonizo* (Faulkner).', 'Los bloques sin punto y aparte de Thomas Bernhard o de *Cinco horas con Mario* (Delibes), que encierran al lector en la voz de Carmen.'],
      s:['Elipsis narrativa', 'Ritmo narrativo', 'Recursos tipográficos'] },
    { n:'Énfasis y final de frase', a:'Posición fuerte',
      d:'En una frase, el lugar de más peso es el final; el segundo, el principio. El medio es la zona de sombra. Lo mismo vale para el párrafo y el capítulo.',
      u:'Coloque al final la palabra o la información que quiere dejar resonando; esconda en medio lo secundario (o la pista que no quiere que se note). Al revisar, mire la última palabra de cada párrafo: es la que se queda.',
      x:['Débil: «Encontraron su cuerpo en el río, tres días después, según dijo la policía.»', 'Fuerte: «Tres días después, según la policía, la encontraron en el río.»', 'Pista escondida: «Llevaba el abrigo de siempre, un periódico doblado, los guantes de piel y cara de haber dormido mal.»'],
      s:['Ritmo de la frase', 'Frase periódica y frase acumulativa', 'Gradación'] },
    { n:'Frase periódica y frase acumulativa', a:'Periodo suspendido · frase suelta',
      d:'En la frase periódica, la oración principal, y con ella el sentido, solo llega al final, tras una serie de elementos que la aplazan. En la acumulativa, la principal va primero y se le van añadiendo detalles, como quien mira cada vez más de cerca.',
      u:'La periódica crea suspensión y solemnidad: el lector espera el verbo. La acumulativa es natural y exploratoria, parece pensamiento sucediendo, y es ideal para describir en movimiento.',
      c:'Periodos suspendidos uno tras otro suenan a discurso de tribuna.',
      x:['Periódica: «Después de treinta años de cartas devueltas, de llamadas colgadas y de navidades en silencio, su padre apareció en la puerta.»', 'Acumulativa: «Su padre apareció en la puerta, más bajo de lo que recordaba, con el sombrero en la mano, mirándose los zapatos.»'],
      s:['Frase larga', 'Énfasis y final de frase', 'Hipérbaton', 'Parataxis e hipotaxis'] },
    { n:'Voz activa y voz pasiva', a:'Pasiva perifrástica · pasiva refleja · impersonal',
      d:'En la activa, el sujeto realiza la acción («Marta rompió el jarrón»); en la pasiva perifrástica, la recibe («El jarrón fue roto»). El español prefiere la pasiva refleja («Se rompió el jarrón») y tiene un recurso precioso para eludir la culpa: el «se» con dativo de implicación («Se me rompió»), que presenta la acción como un accidente.',
      u:'La activa es más directa y viva: es la opción por defecto. La pasiva y el «se» sirven cuando el agente es desconocido o se quiere poner el foco en la víctima, y son excelentes para caracterizar a políticos, burócratas y culpables que no quieren serlo.',
      c:'La pasiva con «ser» es mucho menos frecuente en español que en inglés; abusar de ella, sobre todo en traducciones, produce una prosa acartonada («El documento fue firmado por el director»).',
      x:['Activa: «El guardia abrió la celda.»', 'Pasiva que oculta: «Se cometieron errores.»', 'Accidente fingido: «—Se me ha roto, mamá. No sé cómo.»'],
      s:['Verbos precisos', 'Eufemismo', 'Registro lingüístico'] },
    { n:'Inciso y paréntesis', a:'Aparte · oración intercalada',
      d:'Elemento introducido en mitad de la frase, entre comas, rayas o paréntesis, que la interrumpe para añadir, corregir o comentar.',
      u:'Entre comas, el inciso se integra; entre rayas, se destaca; entre paréntesis, baja la voz: es el lugar del aparte cómplice, de la ironía y de lo que el narrador finge que no es importante.',
      c:'Los incisos largos alejan el sujeto del verbo y obligan a releer. La raya que abre un inciso debe cerrarse siempre, aunque después venga otro signo.',
      x:['«La tía Amelia —que nunca había salido de Zamora— nos explicó París.»', '«Se casaron en mayo (él decía junio, pero él decía muchas cosas).»', 'Nabokov, en *Lolita*, despacha la muerte de la madre de Humbert en un paréntesis de dos palabras: «(picnic, rayo)».'],
      s:['Puntuación expresiva', 'Narrador intruso', 'Ironía'] },
    { n:'Eufonía y cacofonía', a:'Ecos · rimas internas · cacófatos',
      d:'Eufonía es la sucesión de sonidos agradable al oído; cacofonía, la desagradable. Los defectos más comunes en prosa española: las rimas internas involuntarias (sobre todo en -ción, -mente, -ado, -ido), la repetición de un mismo sonido sin intención y el cacófato (unión de palabras que forma otra ridícula o malsonante).',
      u:'Lea en voz alta: es la única manera de detectarlos. Si coordina dos adverbios en -mente, el primero pierde el sufijo: «clara y concisamente». Los mismos sonidos que son defecto por descuido se vuelven recurso cuando se eligen: una frase áspera para una escena áspera.',
      x:['Eco: «La reacción de la población ante la inundación fue de indignación.»', 'Eco en -mente: «Entró lentamente y se sentó silenciosamente.» → «Entró despacio y se sentó en silencio.»', 'Choque de sílabas: «Habló con Concha de la cama de Camila.»'],
      s:['Aliteración', 'Asonancia', 'Ritmo de la frase'] },
    { n:'Prosa poética', a:'Poema en prosa · prosa lírica',
      d:'Prosa que utiliza los medios de la poesía —ritmo marcado, imagen densa, repetición, suspensión de la trama— sin verso.',
      u:'Sirve a los momentos de contemplación, éxtasis, duelo o delirio, en los que importa el estado y no la acción. En una novela funciona como cambio de tempo: unas líneas, un párrafo, un capítulo breve.',
      c:'Mantenida mucho tiempo, cansa y frena la trama; la prosa recargada y sin necesidad («prosa púrpura») es su fracaso.',
      x:['*Platero y yo* (Juan Ramón Jiménez).', 'Las *Leyendas* de Bécquer.', '*Pedro Páramo* (Rulfo), en sus pasajes de Susana San Juan.', '*Las olas* (Virginia Woolf); *El spleen de París* (Baudelaire).'],
      s:['Ritmo de la frase', 'Imágenes sensoriales', 'Pausa descriptiva', 'Maximalismo'] }
  ]},
  { name:'Palabras y registro', items:[
    { n:'Registro lingüístico', a:'Nivel de lengua · registro culto, coloquial, vulgar',
      d:'La variedad de lengua adecuada a cada situación: culto o formal, estándar, coloquial o familiar, vulgar, jerga (de un grupo o profesión), técnico.',
      u:'El registro caracteriza al personaje (edad, clase, región, oficio) y la relación entre quienes hablan. Un cambio de registro en medio de una escena revela un cambio de poder o de emoción.',
      c:'La jerga envejece deprisa; la vulgaridad en dosis masivas deja de impactar.',
      x:['Formal: «Tenga la bondad de esperar un momento.»', 'Coloquial: «Espera un segundito.»', 'Vulgar: «Para el carro, tío.» (España) / «Aguantá un toque, boludo.» (Río de la Plata)', '*La naranja mecánica* (Burgess): una jerga inventada, el *nadsat*.'],
      s:['Tono', 'Idiolecto y marcas de oralidad', 'Voz narrativa', 'Disfemismo', 'Formas de tratamiento'] },
    { n:'Tono', d:'La actitud del narrador (o del texto) ante lo que cuenta y ante el lector: grave, irónico, tierno, cínico, neutro, cómico, elegíaco, épico.',
      u:'El tono es un contrato: se establece en la primera página y dice al lector cómo leer el resto. Puede contrastar con el contenido —horror contado con ligereza, banalidad contada con solemnidad— y ese desfase es uno de los efectos más potentes que existen.',
      c:'Las rupturas de tono involuntarias (un chiste en el momento equivocado) destruyen la confianza del lector.',
      x:['Horror en tono neutro: *La metamorfosis* (Kafka) — despertar convertido en insecto y preocuparse por el trabajo.', 'Lo prodigioso en tono cotidiano: *Cien años de soledad*, donde Remedios la Bella sube al cielo mientras tienden las sábanas.', 'Tragedia en tono cómico: *Trampa 22* (Joseph Heller).'],
      s:['Ironía', 'Voz narrativa', 'Atmósfera', 'Humor y comicidad'] },
    { n:'Elección léxica', a:'Dicción · la palabra justa («le mot juste», Flaubert)',
      d:'La selección de las palabras: concretas o abstractas, específicas o genéricas, sencillas o raras, patrimoniales o cultas.',
      u:'Lo concreto y lo específico hacen ver: no «un árbol», sino «una encina»; no «un coche», sino «un Seat 600 abollado» (o «un vocho» en México). Los nombres exactos dan autoridad al narrador. Elija el vocabulario dentro del mundo del Personaje POV.',
      c:'El término raro solo vale si es el exacto; si no, es exhibición. Y cuidado con las palabras que cambian de sentido entre países: «coger», «concha», «pibe», «guagua».',
      x:['Genérico: «Comió algo y salió.»', 'Específico: «Se tragó de pie medio bocadillo de tortilla frío y salió.»'],
      s:['Verbos precisos', 'Detalle significativo', 'Campo semántico'] },
    { n:'Verbos precisos', a:'Verbos fuertes · economía de adverbios y adjetivos',
      d:'Preferir el verbo preciso al genérico acompañado de adverbio, y el sustantivo exacto al vago con adjetivo.',
      u:'«Se arrastró» en lugar de «caminó lentamente»; «susurró» en vez de «dijo en voz baja»; «choza» en lugar de «casa pequeña y pobre». Al revisar, busque los adverbios en -mente y pregúntese si el verbo no podría hacer el trabajo solo. Desconfíe también de los verbos comodín: hacer, poner, tener, dar, haber.',
      c:'No es una prohibición: el adjetivo inesperado y el adverbio que contradice al verbo («sonrió ferozmente») valen oro.',
      x:['Débil: «Cerró la puerta con mucha fuerza.» → Fuerte: «Dio un portazo.»', 'Débil: «La miró fijamente.» → Fuerte: «La escrutó.»', 'Débil: «Hizo un agujero.» → Fuerte: «Cavó un hoyo.»'],
      s:['Elección léxica', 'Adjetivación expresiva', 'Mostrar, no contar'] },
    { n:'Adjetivación expresiva', a:'Adjetivo antepuesto y pospuesto · doble y triple adjetivación',
      d:'Uso del adjetivo como recurso de estilo: su posición, su número y su combinación. En español, el adjetivo pospuesto suele especificar (distingue un objeto de otros) y el antepuesto suele explicar o valorar (subjetivo, afectivo, poético).',
      u:'Aproveche la posición: «un pobre hombre» (digno de lástima) no es «un hombre pobre» (sin dinero); «un gran hombre» no es «un hombre grande»; «un viejo amigo» no es «un amigo viejo»; «cierta noticia» no es «una noticia cierta». La adjetivación ternaria es muy del modernismo y de Valle-Inclán; Azorín buscaba el adjetivo único y exacto.',
      c:'Dos adjetivos sinónimos valen menos que uno. Las series de tres adjetivos en cada frase convierten la prosa en un catálogo.',
      x:['«Un simple soldado» / «un soldado simple».', '«Fumaba un pensativo cigarrillo» (hipálage).', 'Las *Sonatas* de Valle-Inclán, con sus tríadas de adjetivos sensuales y decadentes.'],
      s:['Hipálage', 'Epíteto', 'Verbos precisos', 'Sinestesia'] },
    { n:'Campo semántico', a:'Campo léxico · isotopía · red de imágenes',
      d:'Conjunto de palabras de un mismo ámbito (el mar, la guerra, la enfermedad, la religión) repartidas por un texto.',
      u:'Un campo semántico discreto y coherente crea unidad y subtexto: describir una cena familiar con vocabulario bélico lo dice todo sin decirlo.',
      x:['«La madre avanzó sobre la fuente, flanqueó al tío y conquistó la última patata.»', 'El vocabulario de enfermedad y podredumbre a lo largo de *Hamlet*.', 'La sequía, la sed y el polvo en *Pedro Páramo* y en los cuentos de *El llano en llamas*.'],
      s:['Metáfora', 'Motivo recurrente', 'Subtexto'] },
    { n:'Idiolecto y marcas de oralidad', a:'Habla característica · muletillas',
      d:'El modo de hablar propio de cada personaje: vocabulario, muletillas, sintaxis, pronunciación sugerida, lo que nunca dice.',
      u:'Prueba: tapando los nombres, ¿se sabe quién habla? Distinga por el ritmo y la elección de palabras más que por la ortografía. Una muletilla o un tic bastan si se usan con moderación.',
      c:'La transcripción fonética pesada («pa’ qué, si ya está to’ hecho») cansa y puede sonar a burla. Sugiera; no transcriba.',
      x:['Sancho Panza y su torrente de refranes.', 'Cantinflas, cuyo hablar enredado dio el verbo «cantinflear», recogido por el diccionario académico.', 'Yoda, Gollum, Hagrid: reconocibles en una sola frase.'],
      s:['Registro lingüístico', 'Regionalismo y variedades del español', 'Anacoluto', 'Caracterización directa e indirecta'] },
    { n:'Arcaísmo', d:'Palabra, forma o construcción que ha caído en desuso.',
      u:'Da color de época en la novela histórica y en la fantasía, o solemnidad. Dosifique: bastan una cadencia antigua y algunas palabras clave para crear la ilusión; el lector quiere creer en la época, no descifrarla.',
      c:'Cuidado con los anacronismos léxicos: un personaje del siglo XVI no se «estresa», no «se enfoca» ni tiene «un problema de autoestima».',
      x:['«Vuestra merced», «asaz», «otrosí», «aína» (pronto), «agora», «ansí», «mesmo», «truje».', 'Don Quijote imita el habla de los libros de caballerías: «Non fuyades, cobardes y viles criaturas».'],
      s:['Neologismo', 'Hipérbaton', 'Pastiche y parodia'] },
    { n:'Neologismo', d:'Palabra nueva, creada por el autor mediante derivación, composición, acronimia o pura invención.',
      u:'Nombra lo que no tiene nombre: realidades de mundos inventados, sensaciones, la lengua de un niño. Funciona cuando se entiende a la primera por el contexto o por su formación.',
      x:['Unamuno llamó «nivola» a *Niebla* para desmarcarse de la novela.', 'Cortázar: los «cronopios» y los «famas»; el glíglico de *Rayuela*.', 'Vicente Huidobro en *Altazor*: «Al horitaña de la montazonte» (horizonte + montaña).', 'Orwell en *1984*: «neolengua», «doblepensar».'],
      s:['Arcaísmo', 'Extranjerismo', 'Jitanjáfora', 'Construcción de mundos'] },
    { n:'Regionalismo y variedades del español', a:'Dialectalismo · americanismo',
      d:'Palabra, expresión o construcción propia de una región o país. El español es una lengua pluricéntrica: la norma de Madrid no es la de Bogotá, México o Buenos Aires, y todas son correctas.',
      u:'Arraiga la historia en un lugar y da autenticidad a las voces. Elija qué variedad usa el narrador (y sea coherente) y deje que los personajes hablen la suya. Use términos que se entiendan por el contexto y evite los glosarios.',
      c:'Compruebe con hablantes de la zona; el pintoresquismo de postal es condescendiente. Y vigile los rasgos de su propia variedad que se cuelan en personajes de otra: un mexicano no dice «coche» ni «vale», un madrileño no dice «carro» ni «ahorita».',
      x:['Miguel Delibes y el habla rural de Castilla en *Los santos inocentes*.', 'Juan Rulfo y el habla de Jalisco en *Pedro Páramo*.', 'José María Arguedas: un español con la sintaxis del quechua en *Los ríos profundos*.'],
      s:['Idiolecto y marcas de oralidad', 'Registro lingüístico', 'Formas de tratamiento'] },
    { n:'Extranjerismo', a:'Préstamo · anglicismo · galicismo · alternancia de lenguas',
      d:'Palabra o expresión de otra lengua usada en el texto. Según la *Ortografía* académica, los extranjerismos crudos (no adaptados) se escriben en cursiva (*software*, *thriller*); los adaptados, en redonda (fútbol, estrés, güisqui).',
      u:'Caracteriza ambientes (el inglés de la empresa, el francés de la alta sociedad decimonónica), personajes emigrados o pedantes, y crea color local. La alternancia de lenguas (español e inglés en Estados Unidos, español y guaraní en Paraguay) es una voz en sí misma.',
      x:['Larra se burló de los galicismos de los petimetres de su tiempo.', 'Los anglicismos americanos: «parquear», «chequear», «el lonche».', 'El *spanglish* de Nueva York y Miami en la narrativa de autores latinos.'],
      s:['Neologismo', 'Registro lingüístico', 'Regionalismo y variedades del español'] },
    { n:'Lugar común', a:'Tópico · cliché · frase hecha',
      d:'Expresión o imagen tan usada que ha perdido su efecto («silencio sepulcral», «el corazón le dio un vuelco», «un escalofrío le recorrió la espalda»).',
      u:'En la narración, sustitúyalo por el detalle concreto y específico. En el diálogo, en cambio, es útil: la gente habla con frases hechas, y un tópico caracteriza. También puede subvertirse, tomándolo al pie de la letra o torciéndole el final.',
      x:['Gastado: «Se quedó blanca como la pared.»', 'Renovado: «Se quedó del color de la pared, y la pared era verde hospital.»', 'Flaubert los coleccionó en su *Diccionario de lugares comunes*.'],
      s:['Comparación', 'Catacresis', 'Extrañamiento', 'Refranes y frases hechas'] },
    { n:'Denotación y connotación', d:'La denotación es el significado literal de una palabra, el del diccionario; la connotación es el halo de asociaciones, afectos y juicios que la acompaña. «Casa», «hogar», «vivienda», «domicilio» y «tugurio» pueden denotar el mismo lugar.',
      u:'Entre sinónimos, elija por la connotación: es la que da el tono y el punto de vista. La palabra que el personaje elige para algo dice lo que piensa de ello: «mi marido», «mi hombre», «el padre de mis hijos», «ese señor».',
      x:['«Delgado» / «esbelto» / «escuálido».', '«Tenaz» / «perseverante» / «cabezota».', '«Murió» / «falleció» / «nos dejó» / «la palmó».'],
      s:['Elección léxica', 'Tono', 'Eufemismo', 'Disfemismo'] },
    { n:'Ambigüedad y anfibología', a:'Polisemia · doble sentido',
      d:'Posibilidad de que una palabra, frase o situación tenga más de una lectura. Puede ser léxica (una palabra con varios significados) o sintáctica (la anfibología: una frase admite dos análisis). En español, el posesivo «su» es una fuente constante de anfibologías.',
      u:'La ambigüedad deliberada es un recurso: profecías que se cumplen de forma inesperada, frases que el lector solo entiende en la segunda lectura, finales que admiten dos interpretaciones. La involuntaria es un defecto que hay que eliminar al revisar.',
      x:['Involuntaria: «Vio al hombre con los prismáticos.» (¿quién tiene los prismáticos?)', 'Involuntaria: «Pedro le dijo a Juan que su coche había desaparecido.» (¿el coche de quién?)', 'Deliberada: las profecías de las brujas en *Macbeth*: ningún hombre «nacido de mujer» podrá dañarlo.', 'Final ambiguo: *Otra vuelta de tuerca* (Henry James) — ¿fantasmas o locura?'],
      s:['Dilogía', 'Narrador no fiable', 'Giro argumental'] },
    { n:'Diminutivos y aumentativos', a:'Sufijos apreciativos',
      d:'En español, los sufijos apreciativos (-ito, -illo, -ico, -ín, -uelo; -ón, -azo, -ote; despectivos -ucho, -ejo, -aco) rara vez hablan solo de tamaño: expresan afecto, ironía, desprecio, cortesía, atenuación o énfasis. Varían mucho por regiones: -ico en Aragón, Murcia y el Caribe («momentico»), -ín en Asturias, -illo en Andalucía, y el diminutivo es mucho más frecuente en casi toda América («ahorita», «cerquita»).',
      u:'Son una marca potentísima de oralidad, de origen y de carácter. El diminutivo puede ser ternura («hijito»), cortesía («¿un cafecito?»), atenuación («es solo un momentito»), ironía («¡qué gracioso el niñito!») o desprecio («un abogadillo de tres al cuarto»). El aumentativo admira («un cochazo», «un mujerón») o rebaja («un poetastro», «un caserón»).',
      c:'En exceso, la narración se vuelve empalagosa, salvo que ese sea el retrato. Y recuerde que muchos están lexicalizados y ya no son diminutivos («bocadillo», «gatillo», «zapatilla», «cigarrillo»).',
      x:['«—¿Y el dinerito? —preguntó, muy mansita.»', '«Tenía un empleíllo, un pisito, una vidita.»', 'En México, «ahorita» puede significar «ahora mismo» o «quién sabe cuándo».'],
      s:['Idiolecto y marcas de oralidad', 'Tono', 'Ironía', 'Regionalismo y variedades del español'] },
    { n:'Refranes y frases hechas', a:'Refranero · locuciones · modismos',
      d:'Refrán: sentencia popular de sabiduría práctica («Quien mucho abarca poco aprieta»). Locución o modismo: grupo de palabras cuyo sentido no se deduce de las partes («meter la pata», «estar en las nubes», «tomar el pelo», «irse por los cerros de Úbeda»).',
      u:'Dan sabor popular y arraigan a un personaje en una generación y un lugar. Pueden torcerse para sorprender o tomarse al pie de la letra para hacer reír. Un refrán da también un buen título o un buen epígrafe.',
      c:'Casi nunca se pueden traducir y cambian de país a país: lo que en España es «estar en Babia» o «estar en la luna de Valencia», en casi todo el ámbito hispánico es «estar en la luna» o «en las nubes», y un mismo refrán cambia de forma de un país a otro. Compruebe que el personaje usa los de su tierra y su época.',
      x:['Sancho Panza, que habla a fuerza de refranes, para desesperación de don Quijote.', '*La Celestina*: los criados se pelean a refrán limpio.', 'Torcido: «Más vale pájaro en mano que explicarle a la policía los ciento que volaban.»'],
      s:['Lugar común', 'Idiolecto y marcas de oralidad', 'Regionalismo y variedades del español', 'Catacresis'] },
    { n:'Tacos e insultos', a:'Palabrotas · interjecciones malsonantes · eufemismos del taco',
      d:'El vocabulario grosero o tabú: tacos, insultos, obscenidades, y sus sustitutos avergonzados («¡caramba!», «¡ostras!», «¡jolín!», «¡córcholis!»; en México «¡híjole!», «¡chin!»; en el Río de la Plata «¡la pucha!»).',
      u:'El taco vale por el contraste: en un personaje que nunca los dice, uno solo hace temblar la página. Quién maldice, cómo y delante de quién caracteriza más que el propio taco. En mundos inventados, crear juramentos propios es una forma económica de mostrar lo que es sagrado.',
      c:'En dosis continua anestesia. Y es el terreno más traicionero de la variación: palabras inocentes en un país son groseras en otro («coger», «concha», «pinche», «pisar»).',
      x:['*La Celestina* y la picaresca no se mordían la lengua.', '*El guardián entre el centeno*: los tacos de Holden, escándalo en 1951.', 'El último «Mierda» de *El coronel no tiene quien le escriba* (García Márquez), que estalla tras un libro entero de dignidad contenida.'],
      s:['Registro lingüístico', 'Disfemismo', 'Construcción de mundos', 'Idiolecto y marcas de oralidad'] },
    { n:'Jerga y argot', a:'Lenguaje de grupo · tecnolecto · germanía · lunfardo',
      d:'Argot: el vocabulario propio de un grupo (estudiantes, presos, militares, delincuentes). Jerga técnica: el vocabulario de una profesión o ciencia. El español tiene argots históricos famosos: la germanía de los rufianes del Siglo de Oro y el lunfardo de Buenos Aires.',
      u:'Dos o tres palabras exactas del oficio bastan para que el lector crea que el personaje es médica, pescador o policía. El contexto debe bastar para entenderlas; el recién llegado que pregunta resuelve el resto.',
      c:'El argot mal aprendido suena falso al instante: investigue o pregunte. Y envejece: el de 1995 fecha el libro en 1995.',
      x:['*Rinconete y Cortadillo* (Cervantes): la germanía del patio de Monipodio.', 'El lunfardo del tango y de Roberto Arlt: «mina», «laburo», «bondi».', 'La jerga hospitalaria: «Entra un politraumatizado, preparad quirófano.»'],
      s:['Registro lingüístico', 'Elección léxica', 'Exposición dosificada', 'Neologismo'] },
    { n:'Nombres de los personajes', a:'Onomástica · nombres parlantes',
      d:'El nombre es la primera caracterización: sugiere época, región, clase y, a veces, destino. Los «nombres parlantes» dicen abiertamente lo que el personaje es.',
      u:'Compruebe que el nombre existía en la época y el medio. Evite nombres parecidos o con la misma inicial entre personajes que comparten escena. Apodos, diminutivos y apellidos muestran quién habla: la misma mujer es «María de la Concepción», «Conchita», «doña Concha» y «la Viuda». No dar nombre también es una elección.',
      x:['Cervantes: Rocinante («rocín antes»), Dulcinea, el Caballero de la Triste Figura.', 'García Márquez repite Aurelianos y José Arcadios para sugerir que la historia de los Buendía da vueltas sobre sí misma.', 'Saramago: nadie tiene nombre en *Ensayo sobre la ceguera* — «el médico», «la mujer del médico», «la chica de las gafas oscuras».', 'Dickens: Scrooge, Gradgrind, Uriah Heep, nombres que ya son caricatura.'],
      t:'El nombre de cada Personaje puede cambiarse en cualquier momento en su ficha: todas las Escenas mostrarán el nuevo.',
      s:['Caracterización directa e indirecta', 'Antonomasia', 'Personaje tipo', 'Formas de tratamiento'] },
    { n:'Repetición y sinónimos', a:'Variación elegante',
      d:'El dilema de quien revisa: repetir la misma palabra o cambiarla por un sinónimo. La tradición escolar manda variar; la buena prosa repite cuando la palabra exacta es una sola.',
      u:'Repita sin miedo los nombres de los personajes, «dijo» y los términos concretos: llamar a un perro, en cinco líneas, «el perro», «el animal», «el can» y «el fiel amigo» distrae más que la repetición. Varíe, eso sí, las palabras raras o muy marcadas, que se notan a la segunda.',
      x:['Variación forzada: «Rubén entró. El joven abogado dejó la cartera. El madrileño de treinta años suspiró.»', 'Repetición correcta: «Rubén entró. Dejó la cartera. Suspiró.»'],
      s:['Repetición y estribillo', 'Elección léxica', 'Perífrasis', 'Verbos de habla y acotaciones'] }
  ]},
  { name:'Imagen, descripción y atmósfera', items:[
    { n:'Imágenes sensoriales', a:'Imaginería',
      d:'Lenguaje que convoca los sentidos: vista, oído, olfato, gusto y tacto, y también movimiento, temperatura, dolor, equilibrio.',
      u:'La vista domina por defecto; el olfato y el tacto son los que más se agarran a la memoria y al cuerpo del lector. Bastan dos o tres detalles sensoriales bien elegidos por escena.',
      x:['«Platero es pequeño, peludo, suave» (Juan Ramón Jiménez, *Platero y yo*): el libro empieza por el tacto.', 'La magdalena mojada en el té que devuelve la infancia al narrador de Proust.', '*El perfume* (Patrick Süskind): una novela entera contada por el olfato.', '«La sala olía a cera y a manzanas viejas.»'],
      s:['Sinestesia', 'Detalle significativo', 'Mostrar, no contar'] },
    { n:'Detalle significativo', a:'Detalle revelador',
      d:'El detalle concreto e inesperado que, por sí solo, vuelve real a un personaje, un lugar o una situación, y sugiere todo lo demás.',
      u:'En lugar del retrato completo, elija el rasgo que solo esa persona tiene. Chéjov: no digas que la luna brilla; muestra su reflejo en un trozo de cristal.',
      c:'Una lista de detalles corrientes (pelo castaño, ojos castaños, estatura media) no hace ver a nadie.',
      x:['El coronel de García Márquez rascando el fondo de la lata de café para sacar la última cucharadita.', '«Llevaba la alianza colgada de una cadena, al cuello.»', '«En la nevera, solo mostaza y una botella de cava.»'],
      s:['Mostrar, no contar', 'Sinécdoque', 'Caracterización directa e indirecta'] },
    { n:'Descripción', a:'Estática y dinámica',
      d:'Representación de lugares, objetos y personajes. La estática suspende la acción para pintar un cuadro; la dinámica se integra en la acción y pasa por la mirada y los gestos de quien está allí.',
      u:'Describa en movimiento y a través del Personaje POV: aquello en lo que se fija lo revela. Organice la mirada (de lo general al detalle, de lejos a cerca) y pregúntese qué emoción debe dejar la descripción.',
      c:'Los lectores se saltan los bloques descriptivos que no cambian nada en la escena.',
      x:['Estática: el arranque de *La Regenta*, «La heroica ciudad dormía la siesta», y la larga vista de Vetusta desde la torre de la catedral.', 'Dinámica: «Cruzó la sala esquivando cajas, apartó una cortina que soltó polvo y dio con la ventana clavada.»'],
      s:['Pausa descriptiva', 'Imágenes sensoriales', 'Atmósfera'] },
    { n:'Atmósfera', a:'Ambiente',
      d:'La impresión emocional dominante de una escena o de un libro —opresión, melancolía, amenaza, ligereza—, creada por el escenario, la luz, el clima, los sonidos y el ritmo de las frases.',
      u:'Seleccione los detalles del escenario que sirven a la emoción y corte los demás. La atmósfera también puede contradecir la acción (un crimen en un día radiante) para mayor efecto.',
      x:['Comala en *Pedro Páramo*: el calor, los murmullos, un pueblo de muertos.', 'La niebla y el barro de Londres al comienzo de *Casa desolada* (Dickens).', 'El páramo en *Cumbres borrascosas* (Emily Brontë).'],
      s:['Falacia patética', 'Tono', 'Descripción'] },
    { n:'Falacia patética', a:'Naturaleza como espejo · pathetic fallacy (Ruskin)',
      d:'Atribución de emociones humanas a la naturaleza y al clima, de modo que el paisaje refleje el estado de ánimo de los personajes.',
      u:'La tormenta en la noche del crimen, la lluvia en el entierro. Funciona mejor cuando es sutil, o invertida: un sol radiante en un día de luto vuelve el luto más cruel.',
      c:'Es uno de los tópicos más gastados del melodrama.',
      x:['La tempestad que acompaña la locura de Lear en *El rey Lear*.', 'La tormenta del desenlace de *Don Álvaro o la fuerza del sino* (duque de Rivas).', 'Los paisajes de Castilla de Antonio Machado, que son a la vez un estado de ánimo.'],
      s:['Personificación', 'Atmósfera', 'Correlato objetivo'] },
    { n:'Correlato objetivo', a:'T. S. Eliot',
      d:'Un objeto, una situación o una cadena de acontecimientos que funciona como fórmula de una emoción: en lugar de nombrar el sentimiento, se presenta la cosa concreta que lo despierta en el lector.',
      u:'Pregúntese: ¿qué objeto, gesto o imagen contiene esta emoción? El duelo puede ser un abrigo que aún huele a alguien; la soledad, una mesa puesta para uno.',
      x:['«Seguía comprando dos barras de pan cada mañana.»', 'El vestido de novia amarillento y los relojes parados de la señorita Havisham en *Grandes esperanzas*.'],
      s:['Mostrar, no contar', 'Símbolo', 'Detalle significativo'] },
    { n:'Motivo recurrente', a:'Leitmotiv',
      d:'Elemento —imagen, objeto, color, sonido, frase, situación— que vuelve a lo largo de la obra y le da unidad temática.',
      u:'Elija dos o tres motivos ligados al tema y hágalos reaparecer en momentos clave, con variaciones. El motivo aún no es símbolo, pero puede llegar a serlo por acumulación.',
      x:['Los espejos, los laberintos y los tigres de Borges.', 'La sangre y el sueño en *Macbeth*.', 'Los trenes en *Ana Karénina*, del primer encuentro al final.', 'La luna en el teatro y la poesía de García Lorca.'],
      t:'Registre los motivos en una Nota asociada a las Escenas donde aparecen: tendrá la lista de todas sus apariciones.',
      s:['Símbolo', 'Repetición y estribillo', 'Siembra y cosecha'] },
    { n:'Tiempos verbales de la narración', a:'Indefinido · imperfecto · pluscuamperfecto · presente histórico',
      d:'La elección de los tiempos es un recurso de estilo. El pretérito perfecto simple (indefinido) cuenta acciones puntuales («entró»); el imperfecto pinta el fondo, el hábito y la duración («entraba siempre a las ocho»); el pluscuamperfecto retrocede («había entrado»); el presente histórico acerca («entra, mira alrededor»). Hay además un uso literario y periodístico del imperfecto de subjuntivo en -ra con valor de pluscuamperfecto («la casa que fuera de su abuelo»).',
      u:'Alterne indefinido e imperfecto como figura y fondo. Pasar al presente en un momento de máxima intensidad, dentro de una narración en pasado, produce un efecto de primer plano. En los diálogos, respete la variación: en España se dice «esta mañana he ido» (pretérito perfecto compuesto para lo ocurrido hoy); en casi toda América, en Canarias y en el noroeste peninsular, «esta mañana fui».',
      c:'En analepsis largas, use el pluscuamperfecto para entrar y salir y pase al indefinido en medio, o el texto se llenará de «había». El «-ra» por pluscuamperfecto, en exceso, suena afectado. El pretérito anterior («hubo entrado») es hoy casi exclusivamente literario.',
      x:['«Llovía. El hombre esperaba bajo el toldo. De pronto, cruzó la calle.»', 'El imperfecto de Flaubert, que da al tiempo el color del tedio.', '*Cien años de soledad* abre con un futuro de pasado («había de recordar») que contiene toda la novela.'],
      s:['Tiempo de la narración', 'Analepsis', 'Escena y sumario'] },
    { n:'Intertextualidad', a:'Alusión · cita · epígrafe',
      d:'Diálogo de un texto con otros: citas, alusiones, reescrituras, epígrafes, personajes y títulos prestados.',
      u:'Añade capas de sentido para quien reconoce la referencia, sin excluir a quien no la reconoce. El epígrafe da la clave de lectura; el título puede ser ya una cita.',
      x:['*Ulises* (Joyce) reescribe la *Odisea* en un día de Dublín.', '«Pierre Menard, autor del *Quijote*» (Borges): un hombre que reescribe el *Quijote* palabra por palabra.', '*El año de la muerte de Ricardo Reis* (Saramago) da vida a un heterónimo de Pessoa.', '*Ancho mar de los Sargazos* (Jean Rhys) cuenta la historia de la «loca del desván» de *Jane Eyre*.'],
      s:['Pastiche y parodia', 'Metaficción'] },
    { n:'Pastiche y parodia', d:'Pastiche: imitación del estilo de un autor, un género o una época, como homenaje o ejercicio. Parodia: imitación con intención cómica o crítica.',
      u:'Útiles para documentos dentro de la novela (cartas, periódicos, informes), para novelas históricas y para la sátira. Imitar bien un estilo es, además, la mejor forma de aprenderlo.',
      x:['*Don Quijote* (Cervantes) parodia los libros de caballerías.', '*La abadía de Northanger* (Jane Austen) parodia la novela gótica.', '*El misterio de la cripta embrujada* (Eduardo Mendoza) parodia la novela negra.', '*El nombre de la rosa* (Umberto Eco): pastiche de crónica medieval y de novela policiaca.'],
      s:['Intertextualidad', 'Humor y comicidad', 'Narración epistolar o documental'] },
    { n:'Humor y comicidad', a:'Comicidad de lenguaje, de situación y de carácter',
      d:'Los tres mecanismos clásicos de la risa: de lenguaje (juegos de palabras, registros desajustados, errores de habla), de situación (equívocos, coincidencias, inversiones) y de carácter (un personaje dominado por una manía o un defecto).',
      u:'El humor nace del desfase: entre lo que se espera y lo que ocurre, entre el tono y el asunto, entre lo que el personaje cree de sí y lo que el lector ve. El alivio cómico antes o después de una escena dura aumenta el impacto de ambas.',
      c:'Explicar el chiste lo mata; los personajes que se ríen de sus propios chistes, también.',
      x:['Los manteos, palizas y discursos de don Quijote y Sancho.', 'El portero borracho justo después del asesinato en *Macbeth*.', 'Enrique Jardiel Poncela, Eduardo Mendoza (*Sin noticias de Gurb*), Terry Pratchett, P. G. Wodehouse.'],
      s:['Ironía', 'Dilogía', 'Tono', 'Regla de tres'] },
    { n:'Impresionismo literario', d:'En lugar de describir el objeto, se registra la sensación que produce en el instante en que se percibe: primero la mancha de color, el brillo, el sonido; después (o nunca) la cosa. Aprendido de Flaubert y los Goncourt, marcó el modernismo hispánico y la prosa de Azorín, Valle-Inclán, Gabriel Miró y Juan Ramón Jiménez.',
      u:'Ponga la cualidad antes que la cosa («una blancura de falda» en lugar de «una falda blanca»), use construcciones impersonales, mezcle sentidos (sinestesia) y desplace adjetivos (hipálage). Ofrece la percepción tal como llega a quien mira: ideal para la focalización interna, la penumbra, el movimiento y la distancia.',
      x:['Azorín en *Castilla*: escenas inmóviles, frases breves, el tiempo que pasa sobre un mismo lugar.', 'Las *Sonatas* de Valle-Inclán: luces, perfumes y rumores antes que objetos.', '«Una blancura se movió en lo oscuro del jardín.»'],
      s:['Hipálage', 'Sinestesia', 'Adjetivación expresiva', 'Color y luz', 'Focalización'] },
    { n:'Retrato', a:'Prosopografía (físico) · etopeya (moral)',
      d:'Descripción de un personaje. La retórica clásica distingue la prosopografía, retrato físico, de la etopeya, retrato del carácter y las costumbres; las dos juntas forman el retrato completo.',
      u:'El retrato realista en bloque, a la entrada del personaje, ha dado paso al retrato disperso: un rasgo ahora, otro más tarde, siempre ligado a una acción. Haga que lo físico sugiera lo moral, y páselo por la mirada de quien observa: el retrato que hace un enamorado no es el de un acreedor. La caricatura elige un solo rasgo y lo exagera.',
      c:'Cuidado con el tópico del personaje que se describe mirándose al espejo.',
      x:['El dómine Cabra de *El Buscón* (Quevedo), el retrato caricaturesco más famoso de la lengua.', 'El escudero del *Lazarillo*, que se pasea con un palillo en los dientes para fingir que ha comido.', 'Retrato a través de otro personaje: Darcy visto por Elizabeth, antes y después de Pemberley.'],
      s:['Caracterización directa e indirecta', 'Detalle significativo', 'Descripción', 'Caricatura y grotesco'] },
    { n:'Hipotiposis', a:'Evidencia · descripción viva · enárgeia',
      d:'Descripción tan animada y detallada de una escena o acción que el lector tiene la impresión de estar viéndola. Es el «poner ante los ojos» de la retórica clásica.',
      u:'Presente de indicativo, verbos de movimiento, detalles sensoriales en sucesión rápida, frases que siguen el ritmo de lo que se ve. Úsela en los momentos que el lector debe guardar como imagen: la batalla, la tormenta, el incendio, la entrada triunfal.',
      x:['La batalla naval en *Trafalgar* (Galdós), vista por el joven Gabriel Araceli.', 'La batalla de Waterloo vista por Fabrice en *La cartuja de Parma* (Stendhal).', 'El auto de fe y la procesión en *Memorial del convento* (Saramago).'],
      s:['Imágenes sensoriales', 'Descripción', 'Mostrar, no contar', 'Tiempos verbales de la narración'] },
    { n:'Écfrasis', a:'Ekphrasis',
      d:'Descripción literaria de una obra de arte visual —un cuadro, una estatua, un escudo, una fotografía—, real o inventada.',
      u:'La obra descrita funciona como espejo de la historia: resume el tema, anuncia lo que vendrá, revela a quien la mira. Describa lo que el personaje ve en ella, no lo que hay. Una fotografía de familia es la écfrasis más frecuente de la novela contemporánea.',
      x:['El escudo de Aquiles en el canto XVIII de la *Ilíada*, el ejemplo fundador.', '*El túnel* (Sabato): la ventanita de un cuadro de Castel, que solo María parece entender.', '*Oda a una urna griega* (Keats).', '*El retrato de Dorian Gray* (Oscar Wilde): el cuadro que envejece.'],
      s:['Mise en abyme', 'Símbolo', 'Descripción', 'Intertextualidad'] },
    { n:'Color y luz', a:'Cromatismo · claroscuro',
      d:'El uso deliberado de los colores y la iluminación en la descripción: una paleta dominante, un color que vuelve, contrastes de luz y sombra.',
      u:'Dé a cada lugar o personaje una paleta, y a la historia un color que acumule sentido. Sea específico: no «azul», sino «azul mono de mecánico». La luz (hora del día, estación, quinqué, neón) decide la atmósfera más que los objetos.',
      c:'Las asociaciones gastadas (rojo pasión, negro muerte) funcionan mejor contradichas.',
      x:['El verde de Lorca, deseo y muerte a la vez: «Verde que te quiero verde».', 'El blanco de los muros y el negro del luto en *La casa de Bernarda Alba* (Lorca).', 'El rojo de las criadas en *El cuento de la criada* (Margaret Atwood).', 'El blanco de *Ensayo sobre la ceguera*: una ceguera luminosa, «un mar de leche».'],
      s:['Motivo recurrente', 'Símbolo', 'Impresionismo literario', 'Atmósfera'] },
    { n:'Contraste y yuxtaposición', d:'Poner una junto a otra, sin comentario, dos imágenes, escenas, tonos o personajes que se iluminan mutuamente por la diferencia.',
      u:'Es el montaje del cine aplicado a la prosa: el sentido nace del corte. Un banquete seguido de una escena de hambre ahorra cualquier discurso. Funciona a escala de frase, de párrafo y de capítulo.',
      x:['En *Madame Bovary*, los comicios agrícolas: los juramentos de amor de Rodolphe entrecortados por la entrega de premios al mejor estiércol.', 'En *La colmena* (Cela), los cafés del Madrid de posguerra frente a las casas donde se pasa hambre.', 'El bautizo y las ejecuciones en *El padrino*.'],
      s:['Antítesis', 'Montaje paralelo', 'Ironía', 'Personaje contraste'] },
    { n:'Caricatura y grotesco', d:'Caricatura: retrato que exagera uno o dos rasgos hasta el ridículo. Grotesco: mezcla de lo cómico con lo deforme, lo monstruoso o lo repugnante, que hace reír e incomoda a la vez.',
      u:'La caricatura es el arma de la sátira: fija a un personaje secundario de una vez para siempre. Lo grotesco sirve para mostrar un mundo descoyuntado: el cuerpo que traiciona, la autoridad ridícula, el horror cotidiano. La tradición española lo ha cultivado como pocas: Quevedo, Goya, Valle-Inclán, Solana.',
      c:'Un personaje principal en caricatura continua pierde humanidad, y el lector deja de interesarse.',
      x:['El dómine Cabra y los internos de su pupilaje en *El Buscón* (Quevedo).', 'Los *Caprichos* y las *Pinturas negras* de Goya, en la pintura.', 'Gógol (*La nariz*, *Almas muertas*); *La metamorfosis* (Kafka).'],
      s:['Hipérbole', 'Humor y comicidad', 'Sátira', 'Animalización y cosificación', 'Esperpento', 'Retrato'] }
  ]},
  { name:'Tonos y estéticas', items:[
    { n:'Sátira', d:'Crítica de vicios, costumbres, instituciones o personas por medio del ridículo. No es un género, sino una intención: puede adoptar la forma de novela, obra de teatro, poema o artículo.',
      u:'Exagere solo un grado más allá de lo real, mantenga la lógica interna y la cara seria. La sátira necesita un blanco nítido y, bajo la risa, indignación.',
      c:'Se queda anticuada cuando desaparece su blanco; y el sermón siempre acecha.',
      x:['Los *Sueños* y *El Buscón* de Quevedo.', 'Los artículos de Larra: *Vuelva usted mañana*, *El castellano viejo*.', '*Los relámpagos de agosto* (Jorge Ibargüengoitia), sobre los generales de la Revolución mexicana.', '*Los viajes de Gulliver* (Swift); *Cándido* (Voltaire); *Rebelión en la granja* (Orwell).'],
      s:['Ironía', 'Caricatura y grotesco', 'Humor y comicidad', 'Alegoría', 'Pastiche y parodia'] },
    { n:'Humor negro', d:'Tratar con ligereza o comicidad lo trágico, lo macabro o lo tabú: la muerte, la enfermedad, la guerra, la crueldad.',
      u:'El efecto viene del tono impasible: cuanto más grave el asunto, más tranquila la voz. Permite mirar de frente lo insoportable y caracteriza a quien vive cerca de ello: soldados, médicos, enterradores.',
      c:'Reírse de las víctimas no es lo mismo que reír con ellas: el blanco debe ser el absurdo, el poder o el propio narrador.',
      x:['*Una modesta proposición* (Swift): resolver el hambre en Irlanda comiéndose a los niños.', '*Las muertas* (Jorge Ibargüengoitia); *Trampa 22* (Heller); *Matadero cinco* (Vonnegut).', '*Las intermitencias de la muerte* (Saramago).', '*Memorias póstumas de Blas Cubas*, dedicadas al primer gusano que royó el cadáver del autor.'],
      s:['Tono', 'Ironía', 'Disfemismo', 'Lítote', 'Absurdo'] },
    { n:'Patetismo y cursilería', a:'Pathos · sentimentalismo · melodrama · bathos',
      d:'El patetismo es la apelación a la compasión y la emoción del lector (el *pathos* de la retórica). Se vuelve sentimentalismo cuando la emoción que pide es mayor de la que la escena justifica, y cae en lo cursi —lo que pretende elegancia o sentimiento y resulta ridículo— o en el *bathos*, el descenso involuntario de lo sublime a lo risible.',
      u:'La emoción fuerte pide contención: cuanto más llora el personaje, menos llora el lector. Muestre el gesto pequeño y deje la lágrima para quien lee. El bathos deliberado, en cambio, es un mecanismo cómico.',
      x:['Contenido: «Dobló el jersey de él y volvió a guardarlo, como todos los jueves.»', 'Sentimental: «Su pobre corazón destrozado sangraba de un dolor infinito.»', 'El folletín y la novela por entregas del XIX; el culebrón televisivo como heredero.', 'Bathos cómico: «¡Oh Muerte, oh Destino, oh Hacienda!»'],
      s:['Correlato objetivo', 'Mostrar, no contar', 'Gradación', 'Lítote', 'Tono'] },
    { n:'Barroco: culteranismo y conceptismo', d:'Las dos grandes corrientes del estilo barroco español, rivales en su tiempo. El culteranismo (o gongorismo, de Góngora) trabaja la forma: cultismos, metáforas audaces, hipérbatos latinizantes, alusiones mitológicas, música verbal. El conceptismo (Quevedo, Gracián) trabaja la idea: agudezas, asociaciones ingeniosas entre conceptos, dilogías, paradojas, antítesis, máxima concisión.',
      u:'El conceptismo enseña a construir una frase como una agudeza y un párrafo como una demostración; da voz a predicadores, abogados, cínicos y narradores sentenciosos. El culteranismo enseña la densidad de la imagen y la libertad del orden. Gracián lo teorizó en *Agudeza y arte de ingenio*.',
      c:'En exceso, se convierte en enigma (culteranismo) o en sofisma y retruécano mecánico (conceptismo).',
      x:['Culterano: «Era del año la estación florida» (Góngora, *Soledades*), por «era primavera».', 'Conceptista: «Lo bueno, si breve, dos veces bueno» (Gracián).', 'Quevedo y Góngora se cruzaron sátiras feroces; Sor Juana, en México, dominó ambos registros.'],
      s:['Hipérbaton', 'Dilogía', 'Retruécano', 'Paradoja', 'Antítesis'] },
    { n:'Realismo y naturalismo', a:'Y su antecedente, el costumbrismo',
      d:'La estética dominante de la segunda mitad del siglo XIX: observar la sociedad contemporánea con exactitud, sin idealizar. El naturalismo lleva el programa más lejos y explica a los personajes por la herencia, el medio y la educación, como en un estudio científico. En España lo preparó el costumbrismo (Larra, Mesonero Romanos, Fernán Caballero), con sus cuadros de tipos y costumbres.',
      u:'Como estilo: descripción minuciosa de los ambientes (la casa explica a quien vive en ella), narrador impersonal, detalle documental, estilo indirecto libre, ironía. Sigue siendo la lengua por defecto de la novela.',
      c:'El inventario exhaustivo cansa; el determinismo quita libertad, y con ella interés, a los personajes.',
      x:['*Fortunata y Jacinta* (Galdós); *La Regenta* (Clarín).', '*Los pazos de Ulloa* (Emilia Pardo Bazán), que además defendió el naturalismo en *La cuestión palpitante*.', '*La barraca* (Vicente Blasco Ibáñez).', '*Madame Bovary* (Flaubert); *Germinal* (Zola).'],
      s:['Descripción', 'Detalle significativo', 'Estilo indirecto libre', 'Verosimilitud'] },
    { n:'Esperpento', a:'Deformación grotesca (Valle-Inclán)',
      d:'Estética creada por Ramón del Valle-Inclán: la realidad española, trágica y absurda a la vez, solo puede mostrarse deformada, como en los espejos cóncavos del callejón del Gato de Madrid. Los personajes se degradan en muñecos, fantoches o animales; lo trágico y lo grotesco se funden.',
      u:'Elija una mirada «desde arriba», sin compasión, y aplíquela con rigor: animalización, cosificación, lenguaje mezclado (culto, popular, jergal), acotaciones que son pequeños poemas sarcásticos. Sirve para la sátira política y para mundos en descomposición.',
      c:'Sin un fondo de verdad dolorosa, se queda en caricatura gratuita.',
      x:['*Luces de bohemia* (Valle-Inclán): «Los héroes clásicos reflejados en los espejos cóncavos dan el Esperpento».', '*Tirano Banderas* (Valle-Inclán), antecedente de la novela del dictador hispanoamericana.', 'Las *Pinturas negras* de Goya, en la pintura.'],
      s:['Caricatura y grotesco', 'Animalización y cosificación', 'Sátira', 'Humor negro'] },
    { n:'Estilo oral', a:'Skaz · narración hablada',
      d:'Narración escrita como si la dijera en voz alta alguien que no es escritor: sintaxis del habla, vacilaciones, repeticiones, apartes, vocabulario popular. La crítica rusa lo llamó *skaz*.',
      u:'Da una voz inconfundible y una gran cercanía. Imagine a quién habla el narrador, dónde y por qué ahora. La oralidad se construye: es una ilusión hecha de ritmo y de algunas marcas, no una transcripción.',
      c:'Difícil de sostener en un libro largo sin cansar; y de traducir.',
      x:['Gógol (*El capote*) y Leskov, los modelos rusos.', 'Los cuentos de *El llano en llamas* (Rulfo), con sus campesinos que hablan solos.', '*Hasta no verte Jesús mío* (Elena Poniatowska), construida sobre la voz de una mujer real.', '*Las aventuras de Huckleberry Finn* (Mark Twain); *Gran Sertón: Veredas* (Guimarães Rosa).'],
      s:['Voz narrativa', 'Idiolecto y marcas de oralidad', 'Anacoluto', 'Estilo directo libre', 'Autor, narrador y narratario'] },
    { n:'Estilo negro', a:'Hard-boiled · prosa de la novela negra',
      d:'La prosa de la novela negra estadounidense de los años veinte a cuarenta: narrador cínico en primera persona, frases secas, diálogo cortante, comparaciones inesperadas, ciudad de noche.',
      u:'Tres ingredientes: observación fría de los detalles, humor de quien ya lo ha visto todo y, de vez en cuando, una comparación sorprendente. El sentimiento existe, pero nunca se confiesa.',
      c:'Imitado en exceso, se convierte en parodia de sí mismo.',
      x:['Dashiell Hammett (*El halcón maltés*) y Raymond Chandler (*El sueño eterno*).', 'Manuel Vázquez Montalbán (la serie de Pepe Carvalho) y Paco Ignacio Taibo II (Héctor Belascoarán Shayne).', 'A la manera de Chandler: «Llamaba tanto la atención como una tarántula en un bizcocho.»'],
      s:['Frase breve', 'Comparación', 'Tono', 'Teoría del iceberg', 'Narrador protagonista'] },
    { n:'Gótico', d:'Estética del miedo y del exceso, nacida en el siglo XVIII: casas antiguas y aisladas, secretos de familia, el pasado que vuelve, lo sobrenatural (o su sospecha), una naturaleza amenazadora.',
      u:'Lo esencial es la atmósfera: el lugar funciona como personaje y como imagen de la mente de quien lo habita. Sugiera más de lo que muestra; la duda —¿hay o no hay fantasma?— da más miedo que la certeza.',
      x:['*El castillo de Otranto* (Horace Walpole), el fundador.', '*Frankenstein*; *Drácula*; *La caída de la Casa Usher* (Poe).', 'Las *Leyendas* de Bécquer (*El monte de las ánimas*, *Los ojos verdes*).', 'Horacio Quiroga (*El almohadón de plumas*); el gótico argentino de Mariana Enríquez.'],
      s:['Atmósfera', 'Falacia patética', 'Suspense y sorpresa', 'Ambigüedad y anfibología'] },
    { n:'Absurdo', d:'Presentación de un mundo sin lógica ni sentido, en el que los personajes se empeñan en actuar como si lo tuviera. La narración trata el disparate con total seriedad.',
      u:'Acepte una premisa imposible y desarróllela con rigor burocrático. Lo cómico y la angustia nacen de la misma fuente: la desproporción entre la calma del tono y la enormidad de lo que pasa.',
      x:['*El proceso* y *El castillo* (Kafka).', '*Esperando a Godot* (Beckett); *La cantante calva* (Ionesco).', '*Tres sombreros de copa* (Miguel Mihura); el teatro de Jardiel Poncela.', '*Historias de cronopios y de famas* (Cortázar); Virgilio Piñera.'],
      s:['Tono', 'Humor negro', 'Verosimilitud', 'Realismo mágico', 'Extrañamiento'] },
    { n:'Maximalismo', d:'Lo contrario del minimalismo: abundancia asumida —frases largas, digresiones, enumeraciones, erudición, muchos personajes e hilos—, voluntad de meter el mundo entero en el libro.',
      u:'Exige energía en la frase y una arquitectura fuerte bajo el exceso. Funciona cuando la abundancia es el tema: una ciudad, una época, una mente que no calla.',
      c:'Sin control, es solo falta de cortes.',
      x:['*Gargantúa y Pantagruel* (Rabelais); *Tristram Shandy* (Sterne).', '*Paradiso* (José Lezama Lima); *Terra nostra* (Carlos Fuentes); *2666* (Roberto Bolaño).', '*Ulises* (Joyce); *La broma infinita* (David Foster Wallace).'],
      s:['Frase larga', 'Enumeración', 'Pausa descriptiva', 'Frase breve'] }
  ]},
  { name:'Apertura, cierre y página', items:[
    { n:'Primera frase', a:'Íncipit',
      d:'La frase que abre el libro. Establece la voz, el tono y el pacto de lectura, y debe plantear una pregunta que obligue a leer la segunda.',
      u:'Puede abrir con una voz, una anomalía, una tesis, un lugar o una muerte anunciada. No tiene que ser espectacular; tiene que ser exacta respecto al libro que promete. Suele ser la última frase en quedar terminada.',
      c:'Arranques gastados: el despertador, el sueño, el parte meteorológico, el personaje ante el espejo.',
      x:['«En un lugar de la Mancha, de cuyo nombre no quiero acordarme…» (Cervantes).', '«Muchos años después, frente al pelotón de fusilamiento…» (García Márquez, *Cien años de soledad*).', '«Vine a Comala porque me dijeron que acá vivía mi padre, un tal Pedro Páramo» (Rulfo).', '«Yo, señor, no soy malo…» (Cela, *La familia de Pascual Duarte*).'],
      s:['Gancho', 'In medias res', 'Voz narrativa', 'Tono', 'Última frase'] },
    { n:'Última frase', a:'Éxplicit · cierre',
      d:'La frase que cierra el libro: la que se queda en el oído y decide la impresión final.',
      u:'Termine en una imagen, un gesto o una réplica, mejor que en una explicación. Un eco de la primera frase o de un motivo cierra el círculo. El ritmo cuenta tanto como el sentido: léala en voz alta.',
      x:['*El coronel no tiene quien le escriba*: una sola palabra malsonante que lo resume todo.', '*Cien años de soledad*: las estirpes condenadas que no tienen una segunda oportunidad sobre la tierra.', '*Pedro Páramo*: el cacique que se desmorona como un montón de piedras.', '*El gran Gatsby*: los botes contra la corriente, arrastrados sin cesar hacia el pasado.'],
      s:['Primera frase', 'Estructura circular', 'Desenlace', 'Énfasis y final de frase', 'Motivo recurrente'] },
    { n:'Título', d:'El primer texto que lee el lector. Puede nombrar al protagonista, el lugar, un objeto o imagen central, el tema, o citar otro texto.',
      u:'Un buen título intriga antes de la lectura y gana un segundo sentido después. Prueba: ¿suena bien en voz alta?, ¿se distingue de los demás en una estantería? Los títulos de capítulo son un recurso aparte: prometen, resumen con ironía o despistan.',
      x:['Cuenta el final: *Crónica de una muerte anunciada*.', 'Imagen que se entiende a mitad de libro: *Rayuela*; *La colmena*.', 'Ironía: *Los santos inocentes*.', 'Familia y no individuo: *Los Buddenbrook*; ausencia: *Esperando a Godot*, *Rebeca*.'],
      s:['Intertextualidad', 'Primera frase', 'Símbolo'] },
    { n:'Recursos tipográficos', a:'Tipografía · notas · mancha de la página',
      d:'El uso expresivo del aspecto visual del texto: cursivas, mayúsculas, tipos de letra, notas al pie, páginas en blanco, disposición de las líneas, imágenes y documentos reproducidos.',
      u:'La cursiva sirve para el énfasis, los pensamientos, las palabras extranjeras y los títulos; las mayúsculas, para gritos y carteles. Las notas al pie crean una segunda voz: erudita, cómica o contradictoria. Cartas, mensajes y recortes ganan con un aspecto propio.',
      c:'El efecto gráfico no sustituye a la frase; y puede perderse en la edición digital o en el audiolibro.',
      x:['*Rayuela* (Cortázar): un «tablero de dirección» propone leer los capítulos en otro orden.', '*Tristram Shandy* (Sterne): una página negra por la muerte de Yorick y otra en blanco para que el lector dibuje.', 'Terry Pratchett: la Muerte habla en VERSALITAS y las notas al pie son chistes.', 'Los caligramas de Apollinaire y de Vicente Huidobro.'],
      s:['Puntuación expresiva', 'Párrafo y espacio en blanco', 'Narración epistolar o documental', 'Metaficción'] }
  ]}
]});
